def create_feishu_document(tenant_id, title, doc_type, folder_token=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid_like(prefix):
        # deterministic-ish, offline: prefix + 26 crockford chars
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256((prefix + "|" + str(uuid.uuid4())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(crock[b % 32])
            if len(out) >= 26:
                break
        return prefix + "".join(out)

    def _record_operation(ops, op_row):
        ops.append(op_row)
        _save("operations.json", ops)

    t0 = time.time()
    ops = _load("operations.json")
    op_id = _ulid_like("op_")
    op = {
        "id": op_id,
        "tenant_id": tenant_id if isinstance(tenant_id, str) else "",
        "tool_name": "create_feishu_document",
        "request_json": {
            "tenant_id": tenant_id,
            "title": title,
            "doc_type": doc_type,
            "folder_token": folder_token,
            "idempotency_key": idempotency_key,
        },
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": idempotency_key,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    _record_operation(ops, op)

    def _finish_success(response, target_drive_item_id=None, target_document_id=None):
        op["status"] = "succeeded"
        op["response_json"] = response
        op["target_drive_item_id"] = target_drive_item_id
        op["target_document_id"] = target_document_id
        op["updated_at"] = _now()
        op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        for i in range(len(ops) - 1, -1, -1):
            if ops[i].get("id") == op_id:
                ops[i] = op
                break
        _save("operations.json", ops)
        return response

    def _finish_error(code, msg, **extra):
        op["status"] = "failed"
        op["error_code"] = code
        op["error_message"] = msg
        op["response_json"] = {"error": {"code": code, "message": msg, **extra}}
        op["updated_at"] = _now()
        op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        for i in range(len(ops) - 1, -1, -1):
            if ops[i].get("id") == op_id:
                ops[i] = op
                break
        _save("operations.json", ops)
        return _err(code, msg, **extra)

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _finish_error("VALIDATION_ERROR", "Invalid tenant_id format.", field="tenant_id")
    if not isinstance(title, str) or not title.strip():
        return _finish_error("VALIDATION_ERROR", "Invalid title.", field="title")
    if not isinstance(doc_type, str) or doc_type not in ("doc", "docx"):
        return _finish_error("VALIDATION_ERROR", "Invalid doc_type.", field="doc_type")
    if folder_token is not None and (not isinstance(folder_token, str) or not folder_token.strip()):
        return _finish_error("VALIDATION_ERROR", "Invalid folder_token.", field="folder_token")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _finish_error("VALIDATION_ERROR", "Invalid idempotency_key.", field="idempotency_key")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        return _finish_error("UNAUTHORIZED", "No tenant connection can serve this request.", tenant_id=tenant_id)
    if tenant.get("status") != "active":
        return _finish_error("UNAUTHORIZED", "Tenant connection is not active.", tenant_status=tenant.get("status"))

    # Rate limit: write operation; derive from operations per tenant per minute
    # Choose conservative default: 60 writes/minute
    limit_per_minute = 60
    now_dt = datetime.datetime.utcnow()
    window_start = now_dt - datetime.timedelta(seconds=60)
    count = 0
    for r in ops:
        if r.get("tenant_id") != tenant_id:
            continue
        ca = _parse_dt(r.get("created_at"))
        if not ca:
            continue
        if ca >= window_start:
            # count write-like tools by default: any tool entry counts for simplicity
            count += 1
    if count > limit_per_minute:
        return _finish_error("RATE_LIMIT", "Tenant rate limit exceeded. Please retry later.", limit_per_minute=limit_per_minute)

    # Idempotency: if an operation with same tenant_id + idempotency_key succeeded, return its response
    if idempotency_key:
        for r in reversed(ops):
            if r.get("tenant_id") == tenant_id and r.get("tool_name") == "create_feishu_document" and r.get("idempotency_key") == idempotency_key and r.get("status") == "succeeded":
                resp = r.get("response_json")
                if isinstance(resp, dict):
                    # also update current op to succeeded, referencing prior response
                    return _finish_success(resp, target_drive_item_id=r.get("target_drive_item_id"), target_document_id=r.get("target_document_id"))

    # Simulate Feishu creation offline:
    # Create drive item + document row
    drive_items = _load("drive_items.json")
    documents = _load("documents.json")

    # Create deterministic-ish Feishu tokens/ids from request (stable across retries if idempotency_key provided)
    seed = f"{tenant_id}|{title.strip()}|{doc_type}|{folder_token or ''}|{idempotency_key or op_id}"
    feishu_doc_id = "doc_" + base64.urlsafe_b64encode(hashlib.sha256(seed.encode("utf-8")).digest())[:16].decode("ascii").rstrip("=")
    feishu_token = ("docx_" if doc_type == "docx" else "doc_") + base64.urlsafe_b64encode(hashlib.sha256((seed + "|token").encode("utf-8")).digest())[:16].decode("ascii").rstrip("=")
    url = f"https://open.feishu.cn/document/{feishu_doc_id}"

    # Upsert drive_item unique(tenant_id, feishu_token, item_type)
    existing_di = next((d for d in drive_items if d.get("tenant_id") == tenant_id and d.get("feishu_token") == feishu_token and d.get("item_type") == doc_type), None)
    now = _now()
    if existing_di:
        drive_item = existing_di
        if drive_item.get("status") in ("deleted",):
            # cannot transition out of deleted
            return _finish_error("INVALID_TRANSITION", "Drive item is deleted and cannot be reused.", drive_item_id=drive_item.get("id"))
        drive_item["title"] = title.strip()
        drive_item["url"] = url
        drive_item["source"] = drive_item.get("source") or "direct_lookup"
        drive_item["status"] = "active"
        drive_item["last_seen_at"] = now
        drive_item["updated_at"] = now
    else:
        parent_item_id = None
        if folder_token:
            parent = next((d for d in drive_items if d.get("tenant_id") == tenant_id and d.get("feishu_token") == folder_token and d.get("item_type") == "folder"), None)
            # If folder is unknown, treat as validation error (missing reference)
            if not parent:
                return _finish_error("NOT_FOUND", "Folder token not found in cache for this tenant.", folder_token=folder_token)
            parent_item_id = parent.get("id")

        drive_item_id = _ulid_like("drv_")
        drive_item = {
            "id": drive_item_id,
            "tenant_id": tenant_id,
            "feishu_token": feishu_token,
            "item_type": doc_type,
            "title": title.strip(),
            "url": url,
            "parent_item_id": parent_item_id,
            "owner_user_id": tenant.get("default_user_id"),
            "created_by_user_id": tenant.get("default_user_id"),
            "source": "direct_lookup",
            "status": "active",
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now,
        }
        drive_items.append(drive_item)

    # Upsert document unique(tenant_id, feishu_document_id)
    existing_doc = next((d for d in documents if d.get("tenant_id") == tenant_id and d.get("feishu_document_id") == feishu_doc_id), None)
    if existing_doc:
        doc = existing_doc
        if doc.get("status") == "deleted":
            return _finish_error("INVALID_TRANSITION", "Document is deleted and cannot be recreated.", document_row_id=doc.get("id"))
        doc["drive_item_id"] = drive_item["id"]
        doc["doc_type"] = doc_type
        doc["title"] = title.strip()
        doc["updated_at"] = now
        doc["status"] = doc.get("status") or "active"
    else:
        doc_row_id = _ulid_like("doc_")
        doc = {
            "id": doc_row_id,
            "tenant_id": tenant_id,
            "drive_item_id": drive_item["id"],
            "feishu_document_id": feishu_doc_id,
            "doc_type": doc_type,
            "title": title.strip(),
            "owner_user_id": tenant.get("default_user_id"),
            "permission": "owner",
            "plain_text_snapshot": None,
            "snapshot_version": 0,
            "last_content_fetched_at": None,
            "last_blocks_fetched_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        documents.append(doc)

    _save("drive_items.json", drive_items)
    _save("documents.json", documents)

    response = {
        "document": {
            "id": doc["id"],
            "tenant_id": tenant_id,
            "feishu_document_id": feishu_doc_id,
            "doc_type": doc_type,
            "title": doc.get("title"),
            "status": doc.get("status"),
        },
        "drive_item": {
            "id": drive_item["id"],
            "feishu_token": drive_item["feishu_token"],
            "item_type": drive_item["item_type"],
            "title": drive_item.get("title"),
            "url": drive_item.get("url"),
            "parent_item_id": drive_item.get("parent_item_id"),
            "status": drive_item.get("status"),
        },
    }
    return _finish_success(response, target_drive_item_id=drive_item["id"], target_document_id=doc["id"])

def get_feishu_document_info(tenant_id, document_id, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256((prefix + "|" + str(uuid.uuid4())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(crock[b % 32])
            if len(out) >= 26:
                break
        return prefix + "".join(out)

    def _finish(op, ops, t0, status, response=None, code=None, msg=None, target_document_id=None, target_drive_item_id=None):
        op["status"] = status
        op["updated_at"] = _now()
        op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        if status == "succeeded":
            op["response_json"] = response
            op["target_document_id"] = target_document_id
            op["target_drive_item_id"] = target_drive_item_id
        else:
            op["error_code"] = code
            op["error_message"] = msg
        # persist update
        for i in range(len(ops) - 1, -1, -1):
            if ops[i].get("id") == op.get("id"):
                ops[i] = op
                break
        _save("operations.json", ops)
        if status == "succeeded":
            return response
        return _err(code, msg, tenant_id=tenant_id, document_id=document_id)

    t0 = time.time()
    ops = _load("operations.json")
    op = {
        "id": _ulid_like("op_"),
        "tenant_id": tenant_id if isinstance(tenant_id, str) else "",
        "tool_name": "get_feishu_document_info",
        "request_json": {"tenant_id": tenant_id, "document_id": document_id, "refresh": refresh},
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": None,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("operations.json", ops)

    # Validation
    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="tenant_id is missing or malformed.")
    if not isinstance(document_id, str) or not document_id.strip():
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="document_id is required.")
    if refresh is not None and not isinstance(refresh, bool):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="refresh must be a boolean when provided.")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Tenant connection not found.")
    if tenant.get("status") != "active":
        return _finish(op, ops, t0, "failed", code="UNAUTHORIZED", msg="Tenant connection is not active.", tenant_status=tenant.get("status"))

    documents = _load("documents.json")
    drive_items = _load("drive_items.json")

    doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == document_id and d.get("tenant_id") == tenant_id), None)
    if doc is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Document not found for this tenant.")

    drive = next((di for di in drive_items if isinstance(di, dict) and di.get("id") == doc.get("drive_item_id")), None)
    drive_id = drive.get("id") if isinstance(drive, dict) else None

    # Offline server: "refresh" updates last_seen_at/updated_at like a successful upstream fetch would.
    now = _now()
    if refresh:
        doc["updated_at"] = now
        # do not invent new fields; keep minimal refresh semantics
        if not doc.get("last_content_fetched_at"):
            pass
        for i in range(len(documents) - 1, -1, -1):
            if documents[i].get("id") == doc["id"]:
                documents[i] = doc
                break
        _save("documents.json", documents)

        if isinstance(drive, dict):
            # mark as seen/active if we "refreshed" successfully
            old_status = drive.get("status")
            if old_status in ("unknown", "inaccessible"):
                # only transition if allowed: unknown->active, inaccessible->active
                drive["status"] = "active"
            drive["last_seen_at"] = now
            drive["updated_at"] = now
            for i in range(len(drive_items) - 1, -1, -1):
                if drive_items[i].get("id") == drive["id"]:
                    drive_items[i] = drive
                    break
            _save("drive_items.json", drive_items)

    response = {
        "document": doc,
        "drive_item": drive if isinstance(drive, dict) else None,
    }
    return _finish(op, ops, t0, "succeeded", response=response, target_document_id=doc.get("id"), target_drive_item_id=drive_id)

