        op["updated_at"] = _now()
        op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        if status == "succeeded":
            op["response_json"] = response
            op["target_document_id"] = target_document_id
            op["target_drive_item_id"] = target_drive_item_id
        else:
            op["error_code"] = code
            op["error_message"] = msg
        for i in range(len(ops) - 1, -1, -1):
            if ops[i].get("id") == op.get("id"):
                ops[i] = op
                break
        _save("operations.json", ops)
        if status == "succeeded":
            return response
        return _err(code, msg, tenant_id=tenant_id, document_id=document_id)

    t0 = time.time()
    ops = _load("operations.json")
    op = {
        "id": _ulid_like("op_"),
        "tenant_id": tenant_id if isinstance(tenant_id, str) else "",
        "tool_name": "get_feishu_document_blocks",
        "request_json": {"tenant_id": tenant_id, "document_id": document_id, "page_size": page_size, "page_token": page_token, "refresh": refresh},
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": None,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("operations.json", ops)

    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="tenant_id is missing or malformed.")
    if not isinstance(document_id, str) or not document_id.strip():
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="document_id is required.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="page_size must be an integer between 1 and 500.")
    if page_token is not None and (not isinstance(page_token, str) or not page_token):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="page_token must be a non-empty string when provided.")
    if refresh is not None and not isinstance(refresh, bool):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="refresh must be a boolean when provided.")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Tenant connection not found.")
    if tenant.get("status") != "active":
        return _finish(op, ops, t0, "failed", code="UNAUTHORIZED", msg="Tenant connection is not active.", tenant_status=tenant.get("status"))

    documents = _load("documents.json")
    drive_items = _load("drive_items.json")
    doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == document_id and d.get("tenant_id") == tenant_id), None)
    if doc is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Document not found for this tenant.")

    drive = next((di for di in drive_items if isinstance(di, dict) and di.get("id") == doc.get("drive_item_id")), None)
    drive_id = drive.get("id") if isinstance(drive, dict) else None

    blocks = _load("document_blocks.json")

    now = _now()
    if refresh:
        # business rule: increment snapshot_version; mark prior blocks stale; new snapshot remains active.
        old_sv = doc.get("snapshot_version")
        if not isinstance(old_sv, int) or old_sv < 0:
            old_sv = 0
        new_sv = old_sv + 1

        # stale old blocks for this document
        changed = False
        for b in blocks:
            if not isinstance(b, dict):
                continue
            if b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("status") in ("active", "stale"):
                if b.get("snapshot_version") != new_sv:
                    if b.get("status") == "active":
                        b["status"] = "stale"
                        b["updated_at"] = now
                        changed = True

        # set document snapshot_version
        doc["snapshot_version"] = new_sv
        doc["last_blocks_fetched_at"] = now
        doc["updated_at"] = now
        for i in range(len(documents) - 1, -1, -1):
            if documents[i].get("id") == doc["id"]:
                documents[i] = doc
                break
        _save("documents.json", documents)

        # keep existing blocks as-is (offline); if there are active blocks, align their snapshot_version to new_sv
        # by upserting same feishu_block_id rows as active for new snapshot (idempotent-ish).
        existing_active = [b for b in blocks if isinstance(b, dict) and b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("status") == "active"]
        if existing_active:
            for b in existing_active:
                # Create a new snapshot row or update if already at new_sv
                if b.get("snapshot_version") == new_sv:
                    continue
                # upsert unique(tenant_id, document_id, feishu_block_id)
                fb = b.get("feishu_block_id")
                if not isinstance(fb, str) or not fb:
                    continue
                target = next((x for x in blocks if isinstance(x, dict) and x.get("tenant_id") == tenant_id and x.get("document_id") == document_id and x.get("feishu_block_id") == fb), None)
                if target is not None:
                    # move to active snapshot
                    target["snapshot_version"] = new_sv
                    target["status"] = "active"
                    target["updated_at"] = now
                    changed = True
        if changed:
            _save("document_blocks.json", blocks)

        if isinstance(drive, dict):
            if drive.get("status") in ("unknown", "inaccessible"):
                drive["status"] = "active"
            drive["last_seen_at"] = now
            drive["updated_at"] = now
            for i in range(len(drive_items) - 1, -1, -1):
                if drive_items[i].get("id") == drive["id"]:
                    drive_items[i] = drive
                    break
            _save("drive_items.json", drive_items)

    # pagination over cached blocks (active + stale), default to active first.
    doc_blocks = [b for b in blocks if isinstance(b, dict) and b.get("tenant_id") == tenant_id and b.get("document_id") == document_id]
    def _sort_key(b):
        status = b.get("status")
        status_rank = 0 if status == "active" else (1 if status == "stale" else 2)
        parent = b.get("parent_feishu_block_id") or ""
        idx = b.get("index_in_parent")
        idx_rank = idx if isinstance(idx, int) and idx >= 0 else 10**9
        return (status_rank, parent, idx_rank, b.get("feishu_block_id") or "", b.get("id") or "")
    doc_blocks.sort(key=_sort_key)

    start = 0
    if page_token:
        try:
            start = int(page_token)
            if start < 0:
                start = 0
        except Exception:
            # treat as validation error per tool contract
            return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="page_token is invalid; expected an opaque token returned by the server.")
    page = doc_blocks[start:start + page_size]
    next_cursor = None
    has_more = start + page_size < len(doc_blocks)
    if has_more:
        next_cursor = str(start + page_size)

    response = {
        "document_id": document_id,
        "snapshot_version": doc.get("snapshot_version"),
        "items": page,
        "total": len(doc_blocks),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    return _finish(op, ops, t0, "succeeded", response=response, target_document_id=doc.get("id"), target_drive_item_id=drive_id)

