        "tool_name": "get_feishu_block_content",
        "request_json": {"tenant_id": tenant_id, "document_id": document_id, "block_id": block_id, "refresh": refresh},
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": None,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("operations.json", ops)

    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="tenant_id is missing or malformed.")
    if not isinstance(document_id, str) or not document_id.strip():
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="document_id is required.")
    if not isinstance(block_id, str) or not block_id.strip():
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="block_id is required.")
    if refresh is not None and not isinstance(refresh, bool):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="refresh must be a boolean when provided.")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Tenant connection not found.")
    if tenant.get("status") != "active":
        return _finish(op, ops, t0, "failed", code="UNAUTHORIZED", msg="Tenant connection is not active.", tenant_status=tenant.get("status"))

    documents = _load("documents.json")
    doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == document_id and d.get("tenant_id") == tenant_id), None)
    if doc is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Document not found for this tenant.")

    blocks = _load("document_blocks.json")
    blk = next((b for b in blocks if isinstance(b, dict) and b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("feishu_block_id") == block_id), None)
    if blk is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Block not found in cache for this document/tenant.")

    now = _now()
    if refresh:
        # offline refresh: mark last seen and update timestamps
        blk["updated_at"] = now
        if blk.get("status") == "stale":
            # legal transition stale->active
            blk["status"] = "active"
        for i in range(len(blocks) - 1, -1, -1):
            if blocks[i].get("id") == blk.get("id"):
                blocks[i] = blk
                break
        _save("document_blocks.json", blocks)

    response = {"block": blk}
    return _finish(op, ops, t0, "succeeded", response=response, target_document_id=doc.get("id"), target_block_id=blk.get("id"))

def search_feishu_documents(tenant_id, query, item_types=None, owner_user_id=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tenants = _load("tenants.json")
    drive_items = _load("drive_items.json")
    documents = _load("documents.json")
    ops = _load("operations.json")

    def _new_id(prefix):
        import hashlib, random
        rnd = hashlib.sha256((now + "|" + str(random.random())).encode("utf-8")).hexdigest()[:16]
        return f"{prefix}_{rnd}"

    def _record_op(tenant_row, status, request_json, response_json=None, error_code=None, error_message=None):
        op = {
            "id": _new_id("op"),
            "tenant_id": tenant_row["id"] if tenant_row else (tenant_id if isinstance(tenant_id, str) else ""),
            "tool_name": "search_feishu_documents",
            "request_json": request_json if isinstance(request_json, dict) else {},
            "target_drive_item_id": None,
            "target_document_id": None,
            "target_block_id": None,
            "status": status,
            "idempotency_key": None,
            "feishu_request_id": None,
            "response_json": response_json,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "updated_at": now
        }
        ops.append(op)
        _save("operations.json", ops)

    # ---- validation ----
    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        tenant_row = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
        _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                   error_code="VALIDATION_ERROR", error_message="tenant_id is missing or malformed")
        return _err("VALIDATION_ERROR", "tenant_id is missing or malformed")

    if not isinstance(query, str) or not query.strip():
        tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)
        _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                   error_code="VALIDATION_ERROR", error_message="query is missing or invalid")
        return _err("VALIDATION_ERROR", "query is missing or invalid")

    allowed_item_types = {"doc", "sheet", "bitable", "mindnote", "slide", "file", "wiki_node", "folder"}
    if item_types is not None:
        if not isinstance(item_types, list) or any((not isinstance(x, str) or x not in allowed_item_types) for x in item_types):
            tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)
            _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                       error_code="VALIDATION_ERROR", error_message="item_types contains unsupported values")
            return _err("VALIDATION_ERROR", "item_types contains unsupported values")

    if owner_user_id is not None and (not isinstance(owner_user_id, str) or not owner_user_id.strip()):
        tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)
        _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                   error_code="VALIDATION_ERROR", error_message="owner_user_id must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "owner_user_id must be a non-empty string when provided")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)
        _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                   error_code="VALIDATION_ERROR", error_message="page_size must be between 1 and 200")
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 200")

    start = 0
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token.strip():
            tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)
            _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                       error_code="VALIDATION_ERROR", error_message="page_token is invalid")
            return _err("VALIDATION_ERROR", "page_token is invalid")
        try:
            decoded = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            start = int(decoded.decode("utf-8"))
            if start < 0:
                raise ValueError("neg")
        except Exception:
            tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)
            _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                       error_code="VALIDATION_ERROR", error_message="page_token could not be decoded")
            return _err("VALIDATION_ERROR", "page_token could not be decoded")

    tenant_row = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant_row:
        _record_op(None, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                   error_code="UNAUTHORIZED", error_message="Unknown tenant connection")
        return _err("UNAUTHORIZED", "Unknown tenant connection")
    if tenant_row.get("status") != "active":
        _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                   error_code="UNAUTHORIZED", error_message="Tenant connection is not active")
        return _err("UNAUTHORIZED", "Tenant connection is not active")

    # rate limit
    minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    recent = sum(1 for o in ops if o.get("tenant_id") == tenant_id and isinstance(o.get("created_at"), str) and o["created_at"] >= minute_ago)
    if recent >= 120:
        _record_op(tenant_row, "failed", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
                   error_code="RATE_LIMIT", error_message="Too many requests for this tenant in the last minute")
        return _err("RATE_LIMIT", "Too many requests for this tenant in the last minute")

    q = query.strip().lower()
    # Search across cached drive_items titles/tokens/urls and document titles
    doc_title_by_drive_item = {}
    for d in documents:
        if d.get("tenant_id") == tenant_id and isinstance(d.get("drive_item_id"), str):
            if isinstance(d.get("title"), str) and d["title"].strip():
                doc_title_by_drive_item[d["drive_item_id"]] = d["title"]

    hits = []
    for it in drive_items:
        if it.get("tenant_id") != tenant_id:
            continue
        if item_types is not None and it.get("item_type") not in item_types:
            continue
        if owner_user_id is not None and it.get("owner_user_id") != owner_user_id:
            continue
        hay = " ".join([
            (it.get("title") or ""),
            (doc_title_by_drive_item.get(it.get("id")) or ""),
            (it.get("feishu_token") or ""),
            (it.get("url") or "")
        ]).lower()
        if q in hay:
            hits.append(it)

    # deterministic sort: active first, then last_seen_at desc, then title asc, then id
    def _key(it):
        status = it.get("status")
        st_rank = 0 if status == "active" else (1 if status == "unknown" else (2 if status == "inaccessible" else 3))
        last_seen = it.get("last_seen_at") or ""
        title = it.get("title") or ""
        return (st_rank, "" if last_seen is None else str(last_seen), title.lower(), it.get("id") or "")
    hits.sort(key=_key, reverse=False)

    total = len(hits)
    page = hits[start:start + page_size]
    next_start = start + len(page)
    has_more = next_start < total
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(str(next_start).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "items": page,
        "page_token": next_token,
        "has_more": has_more,
        "total": total,
        "page_size": page_size
    }
    _record_op(tenant_row, "succeeded", {"tenant_id": tenant_id, "query": query, "item_types": item_types, "owner_user_id": owner_user_id, "page_size": page_size, "page_token": page_token},
               response_json={"returned": len(page), "total": total, "has_more": has_more})
    return resp

def update_feishu_block_text(tenant_id, document_id, block_id, text, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
