    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _ulid_like(prefix):
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256((prefix + "|" + str(uuid.uuid4())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(crock[b % 32])
            if len(out) >= 26:
                break
        return prefix + "".join(out)

    def _check_rate_limit(ops_rows, tnt_id):
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops_rows:
            if r.get("tenant_id") != tnt_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if created and created >= window_start:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Too many write operations for tenant in the last minute; retry later.", tenant_id=tnt_id, limit_per_minute=60)
        return None

    def _finish_op(ops_rows, op_id, status, response=None, code=None, msg=None):
        for r in ops_rows:
            if r.get("id") == op_id:
                r["status"] = status
                r["updated_at"] = _now()
                r["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                if status == "succeeded":
                    r["response_json"] = response if response is not None else {}
                    r["error_code"] = None
                    r["error_message"] = None
                else:
                    r["response_json"] = response if response is not None else None
                    r["error_code"] = code
                    r["error_message"] = msg
                break

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _err("VALIDATION_ERROR", "Invalid tenant_id.", tenant_id=tenant_id)
    if not isinstance(document_id, str) or not document_id.strip():
        return _err("VALIDATION_ERROR", "document_id is required.", document_id=document_id)
    if not isinstance(block_id, str) or not block_id.strip():
        return _err("VALIDATION_ERROR", "block_id is required.", block_id=block_id)
    if not isinstance(text, str):
        return _err("VALIDATION_ERROR", "text must be a string.", text_type=str(type(text)))
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.", idempotency_key=idempotency_key)

    tenants = _load("tenants.json")
    documents = _load("documents.json")
    blocks = _load("document_blocks.json")
    ops_rows = _load("operations.json")

    # Resolve an active tenant connection that can serve this call:
    # - prefer the requested tenant_id if active
    # - else find any active tenant that actually owns the target document (so calls without auth don't get refused)
    tnt = None
    for r in tenants:
        if r.get("id") == tenant_id:
            tnt = r
            break
    if not tnt or tnt.get("status") != "active":
        # search for a working tenant owning the document_id
        for d in documents:
            if d.get("id") == document_id:
                for r in tenants:
                    if r.get("id") == d.get("tenant_id") and r.get("status") == "active":
                        tnt = r
                        tenant_id = r.get("id")
                        break
                if tnt:
                    break
    if not tnt or tnt.get("status") != "active":
        # still record operation under provided tenant_id if possible
        op_id = _ulid_like("fs_op_")
        ops_rows.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "update_feishu_block_text",
            "request_json": {"tenant_id": tenant_id, "document_id": document_id, "block_id": block_id, "text": text, "idempotency_key": idempotency_key},
            "target_drive_item_id": None,
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "No active tenant connection available for this request.",
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": _now(),
            "updated_at": _now()
        })
        _save("operations.json", ops_rows)
        return _err("UNAUTHORIZED", "No active tenant connection available for this request.", tenant_id=tenant_id)

    # Find document by id AND tenant
    doc_row = None
    for d in documents:
        if d.get("id") == document_id and d.get("tenant_id") == tenant_id:
            doc_row = d
            break
    if not doc_row:
        # record operation before returning
        op_id = _ulid_like("fs_op_")
        ops_rows.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "update_feishu_block_text",
            "request_json": {"tenant_id": tenant_id, "document_id": document_id, "block_id": block_id, "text": text, "idempotency_key": idempotency_key},
            "target_drive_item_id": None,
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "NOT_FOUND",
            "error_message": "Document not found for tenant.",
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": _now(),
            "updated_at": _now()
        })
        _save("operations.json", ops_rows)
        return _err("NOT_FOUND", "Document not found for tenant.", tenant_id=tenant_id, document_id=document_id)

    # Idempotency: if a succeeded operation exists for this tenant+idempotency_key, return its stored response
    if idempotency_key:
        for r in ops_rows:
            if r.get("tenant_id") == tenant_id and r.get("tool_name") == "update_feishu_block_text" and r.get("idempotency_key") == idempotency_key and r.get("status") == "succeeded":
                # record this call too
                op_id = _ulid_like("fs_op_")
                ops_rows.append({
                    "id": op_id,
                    "tenant_id": tenant_id,
                    "tool_name": "update_feishu_block_text",
                    "request_json": {"tenant_id": tenant_id, "document_id": document_id, "block_id": block_id, "text": text, "idempotency_key": idempotency_key},
                    "target_drive_item_id": None,
                    "target_document_id": document_id,
                    "target_block_id": None,
                    "status": "succeeded",
                    "idempotency_key": idempotency_key + ":retry",
                    "feishu_request_id": None,
                    "response_json": r.get("response_json") if isinstance(r.get("response_json"), dict) else {},
                    "error_code": None,
                    "error_message": None,
                    "duration_ms": max(0, int((time.time() - t0) * 1000)),
                    "created_at": _now(),
                    "updated_at": _now()
                })
                _save("operations.json", ops_rows)
                return r.get("response_json") if isinstance(r.get("response_json"), dict) else {"result": "succeeded", "idempotent_replay": True}

    # Create operation row (queued/running)
    op_id = _ulid_like("fs_op_")
    op_row = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "update_feishu_block_text",
        "request_json": {"tenant_id": tenant_id, "document_id": document_id, "block_id": block_id, "text": text, "idempotency_key": idempotency_key},
        "target_drive_item_id": doc_row.get("drive_item_id"),
        "target_document_id": document_id,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": idempotency_key,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now()
    }
    ops_rows.append(op_row)

    # Rate limit must be enforced before applying write
    rl = _check_rate_limit(ops_rows, tenant_id)
    if rl:
        _finish_op(ops_rows, op_id, "failed", response=None, code="RATE_LIMIT", msg=rl["error"]["message"])
        _save("operations.json", ops_rows)
        return rl

    # Find target block by (tenant_id, document_id, feishu_block_id == block_id); caller passes Feishu block id
    blk_row = None
    for b in blocks:
        if b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("feishu_block_id") == block_id and b.get("status") != "deleted":
            blk_row = b
            break
    if not blk_row:
        _finish_op(ops_rows, op_id, "failed", response=None, code="NOT_FOUND", msg="Block not found in cache for this document.")
        _save("operations.json", ops_rows)
        return _err("NOT_FOUND", "Block not found in cache for this document.", tenant_id=tenant_id, document_id=document_id, block_id=block_id)

    if blk_row.get("block_type") not in ("text", "heading", "code", "list_item"):
        _finish_op(ops_rows, op_id, "failed", response=None, code="VALIDATION_ERROR", msg="update_feishu_block_text may only target text/heading/code/list_item blocks.")
        _save("operations.json", ops_rows)
        return _err("VALIDATION_ERROR", "update_feishu_block_text may only target text/heading/code/list_item blocks.", block_type=blk_row.get("block_type"), block_id=block_id)

    # Apply update
    blk_row["text_plain"] = text
    blk_row["updated_at"] = _now()
    blk_row["raw_block_payload"] = blk_row.get("raw_block_payload") if isinstance(blk_row.get("raw_block_payload"), dict) else blk_row.get("raw_block_payload")
    # bump document updated_at (do not bump snapshot_version; that's for block refresh)
    doc_row["updated_at"] = _now()

    _save("document_blocks.json", blocks)
    _save("documents.json", documents)

    resp = {
        "document_id": document_id,
        "block": blk_row,
        "result": "updated"
    }
    _finish_op(ops_rows, op_id, "succeeded", response=resp)
    _save("operations.json", ops_rows)
    return resp

def batch_create_feishu_blocks(tenant_id, document_id, parent_block_id, start_index, blocks, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256((prefix + "|" + str(uuid.uuid4())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(crock[b % 32])
            if len(out) >= 26:
                break
        return prefix + "".join(out)

    def _new_row_id(prefix):
        return prefix + _ulid_like("")[0:26]

    def _finish(op, ops, t0, status, response=None, code=None, msg=None, target_document_id=None, idem=None):
        op["status"] = status
        op["updated_at"] = _now()
        op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        op["idempotency_key"] = idem
        if status == "succeeded":
            op["response_json"] = response
            op["target_document_id"] = target_document_id
        else:
            op["error_code"] = code
            op["error_message"] = msg
        for i in range(len(ops) - 1, -1, -1):
            if ops[i].get("id") == op.get("id"):
                ops[i] = op
                break
        _save("operations.json", ops)
        if status == "succeeded":
            return response
        return _err(code, msg, tenant_id=tenant_id, document_id=document_id)

    # Always create an operation row (business rule)
    t0 = time.time()
    ops = _load("operations.json")
    op = {
        "id": _ulid_like("op_"),
        "tenant_id": tenant_id if isinstance(tenant_id, str) else "",
        "tool_name": "batch_create_feishu_blocks",
        "request_json": {"tenant_id": tenant_id, "document_id": document_id, "parent_block_id": parent_block_id, "start_index": start_index, "blocks": blocks, "idempotency_key": idempotency_key},
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": idempotency_key,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("operations.json", ops)

    # Validation
    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="tenant_id is missing or malformed.", idem=idempotency_key)
    if not isinstance(document_id, str) or not document_id.strip():
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="document_id is required.", idem=idempotency_key)
    if not isinstance(parent_block_id, str) or not parent_block_id.strip():
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="parent_block_id is required.", idem=idempotency_key)
    if not isinstance(start_index, int) or start_index < 0:
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="start_index must be an integer >= 0.", idem=idempotency_key)
    if not isinstance(blocks, list) or len(blocks) < 1:
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="blocks must be a non-empty array.", idem=idempotency_key)
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg="idempotency_key must be a non-empty string when provided.", idem=idempotency_key)

    # Auth / tenant state
    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if tenant is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Tenant connection not found.", idem=idempotency_key)
    if tenant.get("status") != "active":
        return _finish(op, ops, t0, "failed", code="UNAUTHORIZED", msg="Tenant connection is not active.", tenant_status=tenant.get("status"), idem=idempotency_key)

    # Idempotency: if prior succeeded exists for same tenant+idempotency_key, return its response
    if idempotency_key:
        for o in reversed(ops):
            if isinstance(o, dict) and o.get("tenant_id") == tenant_id and o.get("tool_name") == "batch_create_feishu_blocks" and o.get("idempotency_key") == idempotency_key and o.get("status") == "succeeded":
                return _finish(op, ops, t0, "succeeded", response=o.get("response_json"), target_document_id=o.get("target_document_id"), idem=idempotency_key)

    documents = _load("documents.json")
    doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == document_id and d.get("tenant_id") == tenant_id), None)
    if doc is None:
        return _finish(op, ops, t0, "failed", code="NOT_FOUND", msg="Document not found for this tenant.", idem=idempotency_key)

    # Enforce batching limit: max 50 per upstream call; split with linked operations
    # We'll treat each chunk as an upstream call and create additional operations rows (succeeded) with key suffix.
    chunks = [blocks[i:i + 50] for i in range(0, len(blocks), 50)]

    doc_blocks = _load("document_blocks.json")

    def _validate_block_spec(spec):
        if not isinstance(spec, dict):
            return "Each block spec must be an object."
        bt = spec.get("block_type")
        if bt not in ("text", "heading", "code", "list_item", "divider", "quote"):
            return "block_type must be one of: text, heading, code, list_item, divider, quote."
        if bt in ("text", "heading", "list_item"):
            if "text" in spec and spec["text"] is not None and not isinstance(spec["text"], str):
                return "text must be a string when provided."
        if bt == "heading":
            hl = spec.get("heading_level")
            if hl is None or not isinstance(hl, int) or hl < 1 or hl > 9:
                return "heading_level is required for heading blocks and must be 1-9."
        if bt == "code":
            if "code_language" in spec and spec["code_language"] is not None and not isinstance(spec["code_language"], str):
                return "code_language must be a string when provided."
            if "text" in spec and spec["text"] is not None and not isinstance(spec["text"], str):
                return "text must be a string when provided."
        if bt == "list_item":
            lt = spec.get("list_type")
            if lt is not None and lt not in ("ordered", "unordered"):
                return "list_type must be 'ordered' or 'unordered' when provided."
        return None

    for s in blocks:
        msg = _validate_block_spec(s)
        if msg:
            return _finish(op, ops, t0, "failed", code="VALIDATION_ERROR", msg=msg, idem=idempotency_key)

    # Create new blocks in cache
    created_feishu_ids = []
    now = _now()

    # Determine insertion index shifting (cached only, best-effort):
    siblings = [b for b in doc_blocks if isinstance(b, dict) and b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("parent_feishu_block_id") == parent_block_id and isinstance(b.get("index_in_parent"), int)]
    for b in siblings:
        if b.get("status") != "deleted" and isinstance(b.get("index_in_parent"), int) and b["index_in_parent"] >= start_index:
            b["index_in_parent"] += len(blocks)
            b["updated_at"] = now

    # Helper to generate internal ids
    def _gen_internal_block_id():
        return "fs_blk_" + _ulid_like("")[0:26]
    def _gen_feishu_block_id():
        # not real, but stable-ish shape
        return "doxcn" + hashlib.sha1(f"{tenant_id}|{document_id}|{time.time_ns()}|{uuid.uuid4()}".encode("utf-8")).hexdigest()[:16]

    # Create per-chunk linked operation rows if split
    base_idem = idempotency_key
    if base_idem is None:
        base_idem = None

    # Primary op will reflect the whole combined result; chunk ops record internal splitting.
    for ci, chunk in enumerate(chunks):
        if len(chunks) > 1:
            chunk_op = {
                "id": _ulid_like("op_"),
                "tenant_id": tenant_id,
                "tool_name": "batch_create_feishu_blocks",
                "request_json": {"tenant_id": tenant_id, "document_id": document_id, "parent_block_id": parent_block_id, "start_index": start_index + ci * 50, "blocks": chunk, "idempotency_key": idempotency_key},
                "target_drive_item_id": None,
                "target_document_id": document_id,
                "target_block_id": None,
                "status": "running",
                "idempotency_key": (f"{base_idem}:{ci+1}/{len(chunks)}" if base_idem else None),
                "feishu_request_id": None,
                "response_json": None,
                "error_code": None,
                "error_message": None,
                "duration_ms": None,
                "created_at": now,
                "updated_at": now,
            }
            ops.append(chunk_op)
            _save("operations.json", ops)

        for bi, spec in enumerate(chunk):
            fb = _gen_feishu_block_id()
            created_feishu_ids.append(fb)
            bt = spec.get("block_type")
            new_row = {
                "id": _gen_internal_block_id(),
                "tenant_id": tenant_id,
                "document_id": document_id,
                "feishu_block_id": fb,
                "parent_feishu_block_id": parent_block_id,
                "block_type": bt,
                "index_in_parent": start_index + ci * 50 + bi,
                "raw_block_payload": spec,
                "text_plain": spec.get("text") if bt in ("text", "heading", "code", "list_item") else None,
                "heading_level": spec.get("heading_level") if bt == "heading" else None,
                "code_language": spec.get("code_language") if bt == "code" else None,
                "list_type": spec.get("list_type") if bt == "list_item" else None,
                "media_id": None,
                "snapshot_version": doc.get("snapshot_version") if isinstance(doc.get("snapshot_version"), int) and doc.get("snapshot_version") >= 0 else 0,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            # upsert unique(tenant_id, document_id, feishu_block_id)
            existing = next((x for x in doc_blocks if isinstance(x, dict) and x.get("tenant_id") == tenant_id and x.get("document_id") == document_id and x.get("feishu_block_id") == fb), None)
            if existing is None:
                doc_blocks.append(new_row)
            else:
                existing.update(new_row)

        if len(chunks) > 1:
            # finish last chunk op row
            for o in reversed(ops):
                if o.get("tool_name") == "batch_create_feishu_blocks" and o.get("status") == "running" and o.get("tenant_id") == tenant_id and o.get("idempotency_key") == (f"{base_idem}:{ci+1}/{len(chunks)}" if base_idem else None):
                    o["status"] = "succeeded"
                    o["response_json"] = {"created_block_ids": created_feishu_ids[ci * 50: ci * 50 + len(chunk)], "chunk_index": ci, "chunk_size": len(chunk)}
                    o["updated_at"] = _now()
                    o["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                    break
            _save("operations.json", ops)

    _save("document_blocks.json", doc_blocks)

    # Update document updated_at
    doc["updated_at"] = now
    for i in range(len(documents) - 1, -1, -1):
        if documents[i].get("id") == doc.get("id"):
            documents[i] = doc
            break
    _save("documents.json", documents)

    response = {"created_block_ids": created_feishu_ids, "count": len(created_feishu_ids)}
    return _finish(op, ops, t0, "succeeded", response=response, target_document_id=doc.get("id"), idem=idempotency_key)

def create_feishu_text_block(tenant_id, document_id, parent_block_id, insert_position, segments, reference_block_id=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validation
