                "insert_position": insert_position, "reference_block_id": reference_block_id,
                "list_type": list_type, "text": text, "indent_level": indent_level,
                "idempotency_key": idempotency_key
            },
            "target_drive_item_id": None,
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "Tenant connection is not active.",
            "duration_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "updated_at": now
        })
        _save("operations.json", ops)
        return _err("UNAUTHORIZED", "Tenant connection is not active.")

    doc = next((d for d in documents if d.get("id") == document_id and d.get("tenant_id") == tenant_id), None)
    if not doc:
        op_id = "op_" + hashlib.sha256(f"{tenant_id}|create_feishu_list_block|{now}|{random.random()}".encode()).hexdigest()[:24]
        ops.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "create_feishu_list_block",
            "request_json": {
                "tenant_id": tenant_id, "document_id": document_id, "parent_block_id": parent_block_id,
                "insert_position": insert_position, "reference_block_id": reference_block_id,
                "list_type": list_type, "text": text, "indent_level": indent_level,
                "idempotency_key": idempotency_key
            },
            "target_drive_item_id": None,
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "NOT_FOUND",
            "error_message": "Document not found for tenant.",
            "duration_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "updated_at": now
        })
        _save("operations.json", ops)
        return _err("NOT_FOUND", "Document not found.")

    # Rate limit (writes)
    window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    def _parse_ts(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None
    recent = 0
    for o in ops:
        if o.get("tenant_id") != tenant_id:
            continue
        ts = _parse_ts(o.get("created_at", ""))
        if ts and ts >= window_start:
            recent += 1
    if recent >= 60:
        op_id = "op_" + hashlib.sha256(f"{tenant_id}|create_feishu_list_block|{now}|{random.random()}".encode()).hexdigest()[:24]
        ops.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "create_feishu_list_block",
            "request_json": {
                "tenant_id": tenant_id, "document_id": document_id, "parent_block_id": parent_block_id,
                "insert_position": insert_position, "reference_block_id": reference_block_id,
                "list_type": list_type, "text": text, "indent_level": indent_level,
                "idempotency_key": idempotency_key
            },
            "target_drive_item_id": doc.get("drive_item_id"),
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded for tenant (writes per minute).",
            "duration_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "updated_at": now
        })
        _save("operations.json", ops)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if idempotency_key:
        existing_op = next((o for o in ops if o.get("tenant_id") == tenant_id and o.get("idempotency_key") == idempotency_key), None)
        if existing_op:
            if existing_op.get("status") == "succeeded":
                blk_id = existing_op.get("target_block_id")
                blk = next((b for b in blocks if b.get("id") == blk_id), None) if blk_id else None
                return {"operation": existing_op, "block": blk, "result": (existing_op.get("response_json") or {}).get("result")}
            return _err("CONFLICT", "Idempotency key already used for a non-succeeded operation.", operation=existing_op)

    sibling_blocks = [b for b in blocks if b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("parent_feishu_block_id") == parent_block_id and b.get("status") != "deleted"]
    ref_blk = None
    if insert_position in ("before", "after"):
        ref_blk = next((b for b in sibling_blocks if b.get("feishu_block_id") == reference_block_id), None)
        if not ref_blk:
            op_id = "op_" + hashlib.sha256(f"{tenant_id}|create_feishu_list_block|{now}|{random.random()}".encode()).hexdigest()[:24]
            ops.append({
                "id": op_id,
                "tenant_id": tenant_id,
                "tool_name": "create_feishu_list_block",
                "request_json": {
                    "tenant_id": tenant_id, "document_id": document_id, "parent_block_id": parent_block_id,
                    "insert_position": insert_position, "reference_block_id": reference_block_id,
                    "list_type": list_type, "text": text, "indent_level": indent_level,
                    "idempotency_key": idempotency_key
                },
                "target_drive_item_id": doc.get("drive_item_id"),
                "target_document_id": document_id,
                "target_block_id": None,
                "status": "failed",
                "idempotency_key": idempotency_key,
                "feishu_request_id": None,
                "response_json": None,
                "error_code": "NOT_FOUND",
                "error_message": "reference_block_id not found under the given parent in cache.",
                "duration_ms": int((time.time() - t0) * 1000),
                "created_at": now,
                "updated_at": now
            })
            _save("operations.json", ops)
            return _err("NOT_FOUND", "reference_block_id not found in cached blocks for this parent.")

    op_id = "op_" + hashlib.sha256(f"{tenant_id}|create_feishu_list_block|{now}|{random.random()}".encode()).hexdigest()[:24]
    op = {
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "create_feishu_list_block",
        "request_json": {
            "tenant_id": tenant_id, "document_id": document_id, "parent_block_id": parent_block_id,
            "insert_position": insert_position, "reference_block_id": reference_block_id,
            "list_type": list_type, "text": text, "indent_level": indent_level,
            "idempotency_key": idempotency_key
        },
        "target_drive_item_id": doc.get("drive_item_id"),
        "target_document_id": document_id,
        "target_block_id": None,
        "status": "queued",
        "idempotency_key": idempotency_key,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op)
    _save("operations.json", ops)

    op["status"] = "running"
    op["updated_at"] = now
    _save("operations.json", ops)

    feishu_block_id = "blk_" + hashlib.sha256(f"{tenant_id}|{document_id}|list_item|{list_type}|{parent_block_id}|{now}|{random.random()}".encode()).hexdigest()[:20]

    def _sib_sort_key(b):
        idx = b.get("index_in_parent")
        return (idx if isinstance(idx, int) else 10**9, b.get("created_at") or "", b.get("id") or "")
    sib_sorted = sorted(sibling_blocks, key=_sib_sort_key)
    have_indices = any(isinstance(b.get("index_in_parent"), int) for b in sib_sorted)
    if have_indices:
        next_idx = 0
        for b in sib_sorted:
            if isinstance(b.get("index_in_parent"), int) and b["index_in_parent"] >= next_idx:
                next_idx = b["index_in_parent"] + 1
        for b in sib_sorted:
            if b.get("index_in_parent") is None:
                b["index_in_parent"] = next_idx
                next_idx += 1
        sib_sorted = sorted(sib_sorted, key=_sib_sort_key)
        if insert_position == "start":
            new_index = 0
            for b in sib_sorted:
                b["index_in_parent"] = (b.get("index_in_parent") or 0) + 1
                b["updated_at"] = now
        elif insert_position == "end":
            new_index = (sib_sorted[-1]["index_in_parent"] + 1) if sib_sorted else 0
        else:
            ref_index = ref_blk.get("index_in_parent")
            if not isinstance(ref_index, int):
                ref_index = 0
            if insert_position == "before":
                new_index = ref_index
                for b in sib_sorted:
                    if b.get("index_in_parent") is not None and b["index_in_parent"] >= new_index:
                        b["index_in_parent"] += 1
                        b["updated_at"] = now
            else:
                new_index = ref_index + 1
                for b in sib_sorted:
                    if b.get("index_in_parent") is not None and b["index_in_parent"] >= new_index:
                        b["index_in_parent"] += 1
                        b["updated_at"] = now
    else:
        new_index = None

    block_row_id = "fs_blk_" + hashlib.sha256(f"{tenant_id}|{document_id}|{feishu_block_id}".encode()).hexdigest()[:24]
    if any(b for b in blocks if b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("feishu_block_id") == feishu_block_id):
        op["status"] = "failed"
        op["error_code"] = "CONFLICT"
        op["error_message"] = "Generated duplicate feishu_block_id."
        op["duration_ms"] = int((time.time() - t0) * 1000)
        op["updated_at"] = now
        _save("operations.json", ops)
        return _err("CONFLICT", "Duplicate block id generated.")

    raw_payload = {
        "type": "list_item",
        "parent_id": parent_block_id,
        "list_type": list_type,
        "text": text,
        "indent_level": indent_level
    }
    block = {
        "id": block_row_id,
        "tenant_id": tenant_id,
        "document_id": document_id,
        "feishu_block_id": feishu_block_id,
        "parent_feishu_block_id": parent_block_id,
        "block_type": "list_item",
        "index_in_parent": new_index,
        "raw_block_payload": raw_payload,
        "text_plain": text,
        "heading_level": None,
        "code_language": None,
        "list_type": list_type,
        "media_id": None,
        "snapshot_version": int(doc.get("snapshot_version") or 0),
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    blocks.append(block)
    _save("document_blocks.json", blocks)

    doc["updated_at"] = now
    _save("documents.json", documents)

    op["status"] = "succeeded"
    op["target_block_id"] = block_row_id
    op["response_json"] = {"result": "created", "feishu_block_id": feishu_block_id}
    op["duration_ms"] = int((time.time() - t0) * 1000)
    op["updated_at"] = now
    _save("operations.json", ops)

    return {"operation": op, "block": block}

def convert_feishu_wiki_to_document_id(tenant_id, wiki_url, **_extra):
    import json, os, datetime, time, re, hashlib, uuid, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ulid_like(prefix):
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256((prefix + "|" + str(uuid.uuid4())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(crock[b % 32])
            if len(out) >= 26:
                break
        return prefix + "".join(out)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _check_rate_limit(ops_rows, tnt_id, is_write):
        if not is_write:
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops_rows:
            if r.get("tenant_id") != tnt_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if created and created >= window_start:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Too many write operations for tenant in the last minute; retry later.", tenant_id=tnt_id, limit_per_minute=60)
        return None

    def _finish(ops_rows, op_row, t0, status, response=None, code=None, msg=None, target_drive_item_id=None, target_document_id=None):
        op_row["status"] = status
        op_row["updated_at"] = _now()
        op_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        if status == "succeeded":
            op_row["response_json"] = response
            op_row["target_drive_item_id"] = target_drive_item_id
            op_row["target_document_id"] = target_document_id
            op_row["error_code"] = None
            op_row["error_message"] = None
        else:
            op_row["error_code"] = code
            op_row["error_message"] = msg
        for i in range(len(ops_rows) - 1, -1, -1):
            if ops_rows[i].get("id") == op_row.get("id"):
                ops_rows[i] = op_row
                break
        _save("operations.json", ops_rows)
        return response if status == "succeeded" else _err(code, msg, tenant_id=tenant_id, wiki_url=wiki_url)

    # Validate (accept broader "wiki node" links; don't over-reject drive links)
    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        ops_rows = _load("operations.json")
        t0 = time.time()
        op_row = {
            "id": _ulid_like("op_"),
            "tenant_id": tenant_id if isinstance(tenant_id, str) else "",
            "tool_name": "convert_feishu_wiki_to_document_id",
            "request_json": {"tenant_id": tenant_id, "wiki_url": wiki_url},
            "target_drive_item_id": None,
            "target_document_id": None,
            "target_block_id": None,
            "status": "running",
            "idempotency_key": None,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "created_at": _now(),
            "updated_at": _now(),
        }
        ops_rows.append(op_row)
        _save("operations.json", ops_rows)
        return _finish(ops_rows, op_row, t0, "failed", code="VALIDATION_ERROR", msg="tenant_id is invalid (expected fs_tnt_... ULID).")

    if not isinstance(wiki_url, str) or not wiki_url.strip():
        ops_rows = _load("operations.json")
        t0 = time.time()
        op_row = {
            "id": _ulid_like("op_"),
            "tenant_id": tenant_id,
            "tool_name": "convert_feishu_wiki_to_document_id",
            "request_json": {"tenant_id": tenant_id, "wiki_url": wiki_url},
            "target_drive_item_id": None,
            "target_document_id": None,
            "target_block_id": None,
            "status": "running",
            "idempotency_key": None,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "created_at": _now(),
            "updated_at": _now(),
        }
        ops_rows.append(op_row)
        _save("operations.json", ops_rows)
        return _finish(ops_rows, op_row, t0, "failed", code="VALIDATION_ERROR", msg="wiki_url must be a non-empty string.")

    t0 = time.time()
    ops_rows = _load("operations.json")
    op_row = {
        "id": _ulid_like("op_"),
        "tenant_id": tenant_id,
        "tool_name": "convert_feishu_wiki_to_document_id",
        "request_json": {"tenant_id": tenant_id, "wiki_url": wiki_url},
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": None,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops_rows.append(op_row)
    _save("operations.json", ops_rows)

    rl = _check_rate_limit(ops_rows, tenant_id, is_write=True)
    if rl:
        return _finish(ops_rows, op_row, t0, "failed", code=rl["error"]["code"], msg=rl["error"]["message"])

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        return _finish(ops_rows, op_row, t0, "failed", code="NOT_FOUND", msg="tenant_id not found.")
    if tenant.get("status") != "active":
        return _finish(ops_rows, op_row, t0, "failed", code="UNAUTHORIZED", msg="Tenant connection is not active.")

    parsed = urllib.parse.urlparse(wiki_url.strip())
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return _finish(ops_rows, op_row, t0, "failed", code="VALIDATION_ERROR", msg="wiki_url must be a valid http/https URL.")

    path = parsed.path or ""
    qs = urllib.parse.parse_qs(parsed.query or "")

    # Best-effort extraction: accept /wiki/<token>, or drive folder/file tokens as wiki nodes too.
    wiki_token = None
    m = re.search(r"/wiki/([^/?#]+)", path)
    if m:
        wiki_token = m.group(1)
    if not wiki_token:
        # common share patterns: /drive/folder/<token> or ...?token=...
        m2 = re.search(r"/drive/(?:folder|file)/([^/?#]+)", path)
        if m2:
            wiki_token = m2.group(1)
    if not wiki_token and "token" in qs and qs["token"]:
        wiki_token = qs["token"][0]

    if not wiki_token or not isinstance(wiki_token, str):
        return _finish(ops_rows, op_row, t0, "failed", code="VALIDATION_ERROR", msg="wiki_url does not contain a resolvable token (/wiki/<token> or /drive/folder/<token> or ?token=...).")

    # Resolve: offline datastore doesn't have a wiki resolver, so use cache-based resolution:
    # If a drive_items wiki_node exists for this token, map to a document if present; else upsert wiki_node and create a placeholder document row.
    drive_items = _load("drive_items.json")
    now = _now()

    # Upsert drive_items wiki_node with source=wiki_convert
    di = next((r for r in drive_items if r.get("tenant_id") == tenant_id and r.get("item_type") == "wiki_node" and r.get("feishu_token") == wiki_token), None)
    if not di:
        di = {
            "id": _ulid_like("fs_itm_"),
            "tenant_id": tenant_id,
            "feishu_token": wiki_token,
            "item_type": "wiki_node",
            "title": None,
            "url": wiki_url.strip(),
            "parent_item_id": None,
            "owner_user_id": None,
            "created_by_user_id": None,
            "source": "wiki_convert",
            "status": "active",
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now,
        }
        drive_items.append(di)
    else:
        # legal transitions: unknown/active/inaccessible/deleted -> active allowed except deleted->... not allowed
        if di.get("status") == "deleted":
            return _finish(ops_rows, op_row, t0, "failed", code="INVALID_TRANSITION", msg="Cached wiki_node is deleted and cannot transition to active without explicit API signal.", target_drive_item_id=di.get("id"))
        di["url"] = wiki_url.strip()
        di["source"] = "wiki_convert"
        di["last_seen_at"] = now
        di["updated_at"] = now
        if di.get("status") in ("unknown", "inaccessible"):
            di["status"] = "active"
    _save("drive_items.json", drive_items)

    # Resolve document id: use existing documents with matching drive_item_id or feishu_document_id == token if already used that way.
    documents = _load("documents.json")
    doc = next((d for d in documents if d.get("tenant_id") == tenant_id and d.get("drive_item_id") == di["id"]), None)
    if not doc:
        # Some deployments store feishu_document_id already as token; check that too.
        doc = next((d for d in documents if d.get("tenant_id") == tenant_id and d.get("feishu_document_id") == wiki_token), None)

    if not doc:
        # Upsert documents row (placeholder mapping) per business rule.
        # Choose doc_type based on token prefix heuristic; default docx.
        doc_type = "docx"
        if wiki_token.startswith("doc"):
            doc_type = "doc"
        feishu_document_id = wiki_token  # best-effort offline resolution
        doc = {
            "id": _ulid_like("fs_doc_"),
            "tenant_id": tenant_id,
            "drive_item_id": di["id"],
            "feishu_document_id": feishu_document_id,
            "doc_type": doc_type,
            "title": di.get("title"),
            "owner_user_id": di.get("owner_user_id"),
            "permission": "unknown",
            "plain_text_snapshot": None,
            "snapshot_version": 0,
            "last_content_fetched_at": None,
            "last_blocks_fetched_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        documents.append(doc)
        _save("documents.json", documents)
    else:
        # Ensure drive_item linkage (upsert semantics)
        changed = False
        if doc.get("drive_item_id") != di["id"]:
            doc["drive_item_id"] = di["id"]
            changed = True
        if doc.get("status") == "deleted":
            # documents.deleted has no outbound transitions
            return _finish(ops_rows, op_row, t0, "failed", code="INVALID_TRANSITION", msg="Resolved document is deleted and cannot be reactivated via wiki conversion.", target_drive_item_id=di.get("id"), target_document_id=doc.get("id"))
        if doc.get("status") in ("inaccessible", "archived"):
            doc["status"] = "active"
            changed = True
        if changed:
            doc["updated_at"] = now
            for i in range(len(documents) - 1, -1, -1):
                if documents[i].get("id") == doc.get("id"):
                    documents[i] = doc
                    break
            _save("documents.json", documents)

    response = {
        "wiki_url": wiki_url.strip(),
        "wiki_token": wiki_token,
        "document_id": doc["id"],
        "feishu_document_id": doc["feishu_document_id"],
        "doc_type": doc["doc_type"],
        "drive_item_id": di["id"],
    }
