                    tenant_id=tenant_id, document_id=document_id)

    # Perform deletion: transition status to deleted (legal from active/stale)
    deleted = []
    for r in rows_to_delete:
        if r.get("status") == "deleted":
            continue
        r["status"] = "deleted"
        r["updated_at"] = _now()
        deleted.append(r.get("feishu_block_id"))

    if not deleted:
        _finish_op(ops_rows, op_id, "failed", response=None, code="NOT_FOUND", msg="No matching blocks were deleted (already deleted or not found).")
        _save("operations.json", ops_rows)
        return _err("NOT_FOUND", "No matching blocks were deleted (already deleted or not found).", tenant_id=tenant_id, document_id=document_id)

    doc_row["updated_at"] = _now()
    _save("document_blocks.json", blocks)
    _save("documents.json", documents)

    resp = {
        "document_id": document_id,
        "deleted_block_ids": deleted,
        "deleted_count": len(deleted),
        "result": "deleted"
    }
    _finish_op(ops_rows, op_id, "succeeded", response=resp)
    _save("operations.json", ops_rows)
