    # Offline "download": produce deterministic placeholder bytes; still enforce "valid feishu_media_id" existence by allowing any non-empty string.
    # Upsert a downloaded media asset row per business rule.
    now = _now()
    if not asset:
        asset = {
            "id": _ulid_like("fs_med_"),
            "tenant_id": tenant_id,
            "document_id": None,
            "feishu_media_id": media_id,
            "content_type": None,
            "byte_size": None,
            "sha256": None,
            "source_kind": "feishu_download",
            "source_uri": "feishu_media_id:" + media_id,
            "bound_block_id": None,
            "status": "downloaded",
            "last_error": None,
            "created_at": now,
            "updated_at": now
        }
        media_assets.append(asset)
    else:
        # legal transitions: pending/uploaded/bound/failed -> downloaded (only bound -> downloaded allowed in lifecycle; but business rule says downloads set downloaded)
        # We'll allow from bound to downloaded, and if already downloaded keep.
        if asset.get("status") not in ("downloaded", "bound"):
            asset["status"] = "downloaded"
        asset["source_kind"] = "feishu_download"
        asset["source_uri"] = "feishu_media_id:" + media_id
        asset["updated_at"] = now

    # create placeholder image bytes (not a real image, but stable). use media_id as payload
    payload = ("FEISHU_MEDIA_PLACEHOLDER:" + media_id).encode("utf-8")
    sha = hashlib.sha256(payload).hexdigest()
    asset["sha256"] = sha
    asset["byte_size"] = len(payload)
    if not asset.get("content_type"):
        asset["content_type"] = "application/octet-stream"

    _save("media_assets.json", media_assets)

    resp = {
        "media_id": media_id,
        "content_type": asset.get("content_type"),
        "byte_size": asset.get("byte_size"),
        "sha256": asset.get("sha256"),
        "data_base64": base64.b64encode(payload).decode("ascii"),
        "media_asset": asset
    }
    _finish_op(ops_rows, op_id, "succeeded", response={"media_id": media_id, "content_type": resp["content_type"], "byte_size": resp["byte_size"], "sha256": resp["sha256"], "media_asset_id": asset.get("id")})
    _save("operations.json", ops_rows)
    return resp

