        return _err("VALIDATION_ERROR", "source_uri is required.", source_uri=source_uri)
    if source_kind == "url":
        try:
            p = urllib.parse.urlparse(source_uri)
            if p.scheme not in ("http", "https") or not p.netloc:
                return _err("VALIDATION_ERROR", "source_uri must be a valid http/https URL when source_kind=url.", source_uri=source_uri)
        except Exception:
            return _err("VALIDATION_ERROR", "source_uri must be a valid URL when source_kind=url.", source_uri=source_uri)
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.", idempotency_key=idempotency_key)

    tenants = _load("tenants.json")
    documents = _load("documents.json")
    blocks = _load("document_blocks.json")
    media_assets = _load("media_assets.json")
    ops_rows = _load("operations.json")

    # Active tenant required
    tnt = None
    for r in tenants:
        if r.get("id") == tenant_id:
            tnt = r
            break
    if not tnt or tnt.get("status") != "active":
        # try to find active tenant that owns the document
        for d in documents:
            if d.get("id") == document_id:
                for r in tenants:
                    if r.get("id") == d.get("tenant_id") and r.get("status") == "active":
                        tnt = r
                        tenant_id = r.get("id")
                        break
                if tnt:
                    break
    if not tnt or tnt.get("status") != "active":
        op_id = _ulid_like("fs_op_")
        ops_rows.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "create_feishu_image_block",
            "request_json": {"tenant_id": tenant_id, "document_id": document_id, "parent_block_id": parent_block_id, "insert_position": insert_position, "reference_block_id": reference_block_id, "source_kind": source_kind, "source_uri": source_uri, "idempotency_key": idempotency_key},
            "target_drive_item_id": None,
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "No active tenant connection available for this request.",
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
