            "created_at": _now(),
            "updated_at": _now()
        })
        _save("operations.json", ops_rows)
        return _err("NOT_FOUND", "Document not found for tenant.", tenant_id=tenant_id, document_id=document_id)

    # Idempotency: if succeeded op exists, return stored response
    if idempotency_key:
        for r in ops_rows:
            if r.get("tenant_id") == tenant_id and r.get("tool_name") == "create_feishu_image_block" and r.get("idempotency_key") == idempotency_key and r.get("status") == "succeeded":
                # record retry operation
                op_id = _ulid_like("fs_op_")
                ops_rows.append({
                    "id": op_id,
                    "tenant_id": tenant_id,
                    "tool_name": "create_feishu_image_block",
                    "request_json": {"tenant_id": tenant_id, "document_id": document_id, "parent_block_id": parent_block_id, "insert_position": insert_position, "reference_block_id": reference_block_id, "source_kind": source_kind, "source_uri": source_uri, "idempotency_key": idempotency_key},
