    # Create an empty image block in document_blocks
    now = _now()
    # choose index_in_parent
    siblings = [b for b in blocks if b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("parent_feishu_block_id") == parent_block_id and b.get("status") != "deleted"]
    idxs = [b.get("index_in_parent") for b in siblings if isinstance(b.get("index_in_parent"), int)]
    max_idx = max(idxs) if idxs else -1
    index_in_parent = None
    if insert_position in ("start", "end"):
        if siblings and len(idxs) == len(siblings):
            index_in_parent = 0 if insert_position == "start" else (max_idx + 1)
        else:
            index_in_parent = max_idx + 1 if insert_position == "end" else 0
    else:
        # before/after reference: if can resolve reference index, use it
        ref = None
        for b in siblings:
            if b.get("feishu_block_id") == reference_block_id:
                ref = b
                break
        if ref and isinstance(ref.get("index_in_parent"), int):
            index_in_parent = ref.get("index_in_parent") + (1 if insert_position == "after" else 0)
        else:
            # fallback append
            index_in_parent = max_idx + 1

    new_block = {
        "id": _ulid_like("fs_blk_"),
        "tenant_id": tenant_id,
        "document_id": document_id,
