        "created_at": now,
        "updated_at": now
    }
    blocks.append(new_block)

    # Create media_assets row pending -> uploaded -> bound (offline simulation)
    guessed_ct = None
    if source_kind == "url":
        path = urllib.parse.urlparse(source_uri).path
        guessed_ct = mimetypes.guess_type(path)[0]
    else:
        guessed_ct = mimetypes.guess_type(source_uri)[0]
    asset = {
        "id": _ulid_like("fs_med_"),
        "tenant_id": tenant_id,
        "document_id": document_id,
        "feishu_media_id": None,
        "content_type": guessed_ct or "application/octet-stream",
        "byte_size": None,
        "sha256": None,
        "source_kind": source_kind,
        "source_uri": source_uri,
        "bound_block_id": new_block["id"],
        "status": "pending",
        "last_error": None,
        "created_at": now,
        "updated_at": now
    }
    media_assets.append(asset)

    # "Upload"
    payload = ("UPLOAD_SRC:" + source_kind + ":" + source_uri).encode("utf-8")
    asset["sha256"] = hashlib.sha256(payload).hexdigest()
    asset["byte_size"] = len(payload)
    asset["feishu_media_id"] = "img_v3_" + hashlib.sha1((asset["sha256"] + "|" + tenant_id).encode("utf-8")).hexdigest()[:14]
    asset["status"] = "uploaded"
    asset["updated_at"] = _now()

    # "Bind"
    asset["status"] = "bound"
    asset["updated_at"] = _now()
    new_block["media_id"] = asset["feishu_media_id"]
    new_block["raw_block_payload"] = {"type": "image", "media_id": asset["feishu_media_id"], "source_kind": source_kind}
    new_block["updated_at"] = _now()

    doc_row["updated_at"] = _now()

    _save("document_blocks.json", blocks)
    _save("media_assets.json", media_assets)
    _save("documents.json", documents)

    resp = {
        "document_id": document_id,
        "block": new_block,
        "media_asset": asset,
        "result": "created"
    }
    _finish_op(ops_rows, op_id, "succeeded", response={"document_id": document_id, "block_id": new_block["id"], "feishu_block_id": new_block["feishu_block_id"], "media_asset_id": asset["id"], "feishu_media_id": asset["feishu_media_id"]})
    _save("operations.json", ops_rows)
    return resp

