        _save("operations.json", ops_rows)
        return _err("UNAUTHORIZED", "No active tenant connection available for this request.", tenant_id=tenant_id)

    # Find document row
    doc_row = None
    for d in documents:
        if d.get("id") == document_id and d.get("tenant_id") == tenant_id:
            doc_row = d
            break
    if not doc_row:
        op_id = _ulid_like("fs_op_")
        ops_rows.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "upload_and_bind_image_to_block",
            "request_json": {"tenant_id": tenant_id, "document_id": document_id, "block_id": block_id, "source_kind": source_kind, "source_uri": source_uri, "content_type": content_type, "idempotency_key": idempotency_key},
            "target_drive_item_id": None,
            "target_document_id": document_id,
            "target_block_id": block_id,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "NOT_FOUND",
            "error_message": "Document not found for tenant.",
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": _now(),
            "updated_at": _now()
        })
        _save("operations.json", ops_rows)
        return _err("NOT_FOUND", "Document not found for tenant.", tenant_id=tenant_id, document_id=document_id)

    # Idempotency: if succeeded op exists, return stored response
    if idempotency_key:
        for r in ops_rows:
            if r.get("tenant_id") == tenant_id and r.get("tool_name") == "upload_and_bind_image_to_block" and r.get("idempotency_key") == idempotency_key and r.get("status") == "succeeded":
                op_id2 = _ulid_like("fs_op_")
                ops_rows.append({
                    "id": op_id2,
                    "tenant_id": tenant_id,
                    "tool_name": "upload_and_bind_image_to_block",
                    "request_json": {"tenant_id": tenant_id, "document_id": document_id, "block_id": block_id, "source_kind": source_kind, "source_uri": source_uri, "content_type": content_type, "idempotency_key": idempotency_key},
                    "target_drive_item_id": doc_row.get("drive_item_id"),
                    "target_document_id": document_id,
                    "target_block_id": block_id,
                    "status": "succeeded",
                    "idempotency_key": idempotency_key + ":retry",
                    "feishu_request_id": None,
                    "response_json": r.get("response_json") if isinstance(r.get("response_json"), dict) else {},
                    "error_code": None,
                    "error_message": None,
                    "duration_ms": max(0, int((time.time() - t0) * 1000)),
                    "created_at": _now(),
                    "updated_at": _now()
                })
                _save("operations.json", ops_rows)
                return r.get("response_json") if isinstance(r.get("response_json"), dict) else {"result": "succeeded", "idempotent_replay": True}

    # Create operation row
    op_id = _ulid_like("fs_op_")
    ops_rows.append({
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "upload_and_bind_image_to_block",
        "request_json": {"tenant_id": tenant_id, "document_id": document_id, "block_id": block_id, "source_kind": source_kind, "source_uri": source_uri, "content_type": content_type, "idempotency_key": idempotency_key},
        "target_drive_item_id": doc_row.get("drive_item_id"),
        "target_document_id": document_id,
        "target_block_id": block_id,
        "status": "running",
        "idempotency_key": idempotency_key,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now()
    })

    rl = _check_rate_limit(ops_rows, tenant_id)
    if rl:
        _finish_op(ops_rows, op_id, "failed", response=None, code="RATE_LIMIT", msg=rl["error"]["message"])
        _save("operations.json", ops_rows)
        return rl

    # Find target block by internal id (fs_blk_...) and ensure image type
    blk = None
    for b in blocks:
        if b.get("id") == block_id and b.get("tenant_id") == tenant_id and b.get("document_id") == document_id and b.get("status") != "deleted":
            blk = b
            break
    if not blk:
        _finish_op(ops_rows, op_id, "failed", response=None, code="NOT_FOUND", msg="Block not found for tenant/document.")
        _save("operations.json", ops_rows)
        return _err("NOT_FOUND", "Block not found for tenant/document.", tenant_id=tenant_id, document_id=document_id, block_id=block_id)

    if blk.get("block_type") != "image":
        _finish_op(ops_rows, op_id, "failed", response=None, code="VALIDATION_ERROR", msg="Target block is not an image block.")
        _save("operations.json", ops_rows)
        return _err("VALIDATION_ERROR", "Target block is not an image block.", block_type=blk.get("block_type"), block_id=block_id)

    # Must be empty media_id to bind unless replacement explicitly allowed (not in this tool signature), so only allow empty.
    if blk.get("media_id"):
        _finish_op(ops_rows, op_id, "failed", response=None, code="CONFLICT", msg="Image block already has media_id; replacement requires a replace flag (not provided).")
        _save("operations.json", ops_rows)
        return _err("CONFLICT", "Image block already has media_id; replacement requires a replace flag (not provided).", media_id=blk.get("media_id"), block_id=block_id)

    # Create media_assets row pending -> uploaded -> bound
    now = _now()
    guessed_ct = content_type
    if not guessed_ct:
        if source_kind == "url":
            path = urllib.parse.urlparse(source_uri).path
            guessed_ct = mimetypes.guess_type(path)[0]
        else:
            guessed_ct = mimetypes.guess_type(source_uri)[0]
    asset = {
        "id": _ulid_like("fs_med_"),
        "tenant_id": tenant_id,
        "document_id": document_id,
        "feishu_media_id": None,
        "content_type": guessed_ct or "application/octet-stream",
        "byte_size": None,
        "sha256": None,
        "source_kind": source_kind,
        "source_uri": source_uri,
        "bound_block_id": blk.get("id"),
        "status": "pending",
        "last_error": None,
        "created_at": now,
        "updated_at": now
    }
    media_assets.append(asset)

    payload = ("UPLOAD_SRC:" + source_kind + ":" + source_uri).encode("utf-8")
    asset["sha256"] = hashlib.sha256(payload).hexdigest()
    asset["byte_size"] = len(payload)
    asset["feishu_media_id"] = "img_v3_" + hashlib.sha1((asset["sha256"] + "|" + tenant_id).encode("utf-8")).hexdigest()[:14]
    asset["status"] = "uploaded"
    asset["updated_at"] = _now()

    # Bind
    asset["status"] = "bound"
    asset["updated_at"] = _now()
    blk["media_id"] = asset["feishu_media_id"]
    blk["raw_block_payload"] = {"type": "image", "media_id": asset["feishu_media_id"], "source_kind": source_kind}
    blk["updated_at"] = _now()
    doc_row["updated_at"] = _now()

    _save("media_assets.json", media_assets)
    _save("document_blocks.json", blocks)
    _save("documents.json", documents)

    resp = {
        "document_id": document_id,
        "block": blk,
        "media_asset": asset,
        "result": "bound"
    }
    _finish_op(ops_rows, op_id, "succeeded", response={"document_id": document_id, "block_id": blk.get("id"), "media_asset_id": asset.get("id"), "feishu_media_id": asset.get("feishu_media_id")})
    _save("operations.json", ops_rows)
    return resp

def get_feishu_root_folder_info(tenant_id, user_id=None, refresh=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        t = int(time.time() * 1000)
        ts = t
        out = []
        for _ in range(10):
            out.append(_CROCK[ts % 32])
            ts //= 32
        ts_part = "".join(reversed(out))
        rnd = "".join(_CROCK[(t * 1103515245 + 12345 + i * 2654435761) % 32] for i in range(16))
        return f"{prefix}{ts_part}{rnd}"

    def _validate_ulid(value, pattern, field):
        if not isinstance(value, str):
            return f"{field} must be a string"
        if not re.match(pattern, value):
            return f"{field} is invalid"
        return None

    def _record_op(ops, op):
        ops.append(op)
        _save("operations.json", ops)

    def _set_op_final(ops, op_id, status, response_json=None, error_code=None, error_message=None, duration_ms=None):
        now = _now_iso()
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = status
                r["updated_at"] = now
                if duration_ms is not None:
                    r["duration_ms"] = duration_ms
                if response_json is not None:
                    r["response_json"] = response_json
                if error_code is not None:
                    r["error_code"] = error_code
                if error_message is not None:
                    r["error_message"] = error_message
                _save("operations.json", ops)
                return

    start = time.time()
    ops = _load("operations.json")

    v = _validate_ulid(tenant_id, r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", "tenant_id")
    op_id = _ulid_like("fs_op_")
    op = {
        "id": op_id,
        "tenant_id": tenant_id if isinstance(tenant_id, str) else "unknown",
        "tool_name": "get_feishu_root_folder_info",
        "request_json": {"tenant_id": tenant_id, "user_id": user_id, "refresh": refresh},
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": None,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso()
    }
    _record_op(ops, op)

    if v:
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message=v, duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", v)

    if user_id is not None and not isinstance(user_id, str):
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="user_id must be a string when provided.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "user_id must be a string when provided.")
    if refresh is not None and not isinstance(refresh, bool):
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="refresh must be a boolean when provided.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided.")

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        _set_op_final(ops, op_id, "failed", error_code="NOT_FOUND", error_message="Tenant not found.", duration_ms=int((time.time()-start)*1000))
        return _err("NOT_FOUND", "Tenant not found.")
    if tenant.get("status") != "active":
        _set_op_final(ops, op_id, "failed", error_code="UNAUTHORIZED", error_message="Tenant connection is not active.", duration_ms=int((time.time()-start)*1000))
        return _err("UNAUTHORIZED", "Tenant connection is not active.")

    effective_user_id = user_id or tenant.get("default_user_id")
    if effective_user_id is None:
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="user_id is required when tenant has no default_user_id.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "user_id is required when tenant has no default_user_id.")

    drive_items = _load("drive_items.json")

    # Cache key: per tenant root folder (parent_item_id null, item_type folder, source root_lookup)
    root_row = None
    for it in drive_items:
        if it.get("tenant_id") == tenant_id and it.get("item_type") == "folder" and it.get("parent_item_id") is None and it.get("source") == "root_lookup":
            root_row = it
            break

    # If refresh requested, we "refresh" the cached record (offline: deterministic token)
    do_refresh = bool(refresh) if refresh is not None else False
    if root_row is None or do_refresh:
        token = "fld_root_" + tenant.get("feishu_tenant_key", tenant_id)[-12:]
        url = "https://drive.feishu.cn/drive/folder/" + token
        now = _now_iso()
        if root_row is None:
            root_id = _ulid_like("fs_drv_")
            root_row = {
                "id": root_id,
                "tenant_id": tenant_id,
                "feishu_token": token,
                "item_type": "folder",
                "title": "Root",
                "url": url,
                "parent_item_id": None,
                "owner_user_id": effective_user_id,
                "created_by_user_id": effective_user_id,
                "source": "root_lookup",
                "status": "active",
                "last_seen_at": now,
                "created_at": now,
                "updated_at": now
            }
            drive_items.append(root_row)
        else:
            # transition unknown/inaccessible -> active is allowed; deleted -> not allowed (but should not happen for root)
            root_row["feishu_token"] = token
            root_row["url"] = url
            root_row["owner_user_id"] = root_row.get("owner_user_id") or effective_user_id
            root_row["last_seen_at"] = now
            if root_row.get("status") in ("unknown", "inaccessible"):
                root_row["status"] = "active"
            root_row["updated_at"] = now
        _save("drive_items.json", drive_items)

    op["target_drive_item_id"] = root_row.get("id")
    _save("operations.json", ops)

    response = {
        "tenant_id": tenant_id,
        "user_id": effective_user_id,
        "root_folder": {
            "drive_item_id": root_row.get("id"),
            "folder_token": root_row.get("feishu_token"),
            "title": root_row.get("title"),
            "url": root_row.get("url"),
            "status": root_row.get("status"),
            "last_seen_at": root_row.get("last_seen_at"),
            "updated_at": root_row.get("updated_at"),
        }
    }
    _set_op_final(ops, op_id, "succeeded", response_json=response, duration_ms=int((time.time()-start)*1000))
    return response

def get_feishu_folder_files(tenant_id, folder_token, page_size=None, page_token=None, include_deleted=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
