        ts = t
        out = []
        for _ in range(10):
            out.append(_CROCK[ts % 32])
            ts //= 32
        ts_part = "".join(reversed(out))
        rnd = "".join(_CROCK[(t * 1103515245 + 12345 + i * 2654435761) % 32] for i in range(16))
        return f"{prefix}{ts_part}{rnd}"

    def _validate_ulid(value, pattern, field):
        if not isinstance(value, str):
            return f"{field} must be a string"
        if not re.match(pattern, value):
            return f"{field} is invalid"
        return None

    def _record_op(ops, op):
        ops.append(op)
        _save("operations.json", ops)

    def _set_op_final(ops, op_id, status, response_json=None, error_code=None, error_message=None, duration_ms=None):
        now = _now_iso()
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = status
                r["updated_at"] = now
                if duration_ms is not None:
                    r["duration_ms"] = duration_ms
                if response_json is not None:
                    r["response_json"] = response_json
                if error_code is not None:
                    r["error_code"] = error_code
                if error_message is not None:
                    r["error_message"] = error_message
                _save("operations.json", ops)
                return

    start = time.time()
    ops = _load("operations.json")

    v = _validate_ulid(tenant_id, r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", "tenant_id")
    op_id = _ulid_like("fs_op_")
    op = {
        "id": op_id,
        "tenant_id": tenant_id if isinstance(tenant_id, str) else "unknown",
        "tool_name": "get_feishu_folder_files",
        "request_json": {
            "tenant_id": tenant_id,
            "folder_token": folder_token,
            "page_size": page_size,
            "page_token": page_token,
            "include_deleted": include_deleted
        },
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": None,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso()
    }
    _record_op(ops, op)

    if v:
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message=v, duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", v)
    if not isinstance(folder_token, str) or not folder_token.strip():
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="folder_token must be a non-empty string.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "folder_token must be a non-empty string.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="page_size must be an integer between 1 and 200.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if page_token is not None and not isinstance(page_token, str):
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="page_token must be a string when provided.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "page_token must be a string when provided.")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="include_deleted must be a boolean when provided.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean when provided.")
    include_deleted = bool(include_deleted) if include_deleted is not None else False

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        _set_op_final(ops, op_id, "failed", error_code="NOT_FOUND", error_message="Tenant not found.", duration_ms=int((time.time()-start)*1000))
        return _err("NOT_FOUND", "Tenant not found.")
    if tenant.get("status") != "active":
        _set_op_final(ops, op_id, "failed", error_code="UNAUTHORIZED", error_message="Tenant connection is not active.", duration_ms=int((time.time()-start)*1000))
        return _err("UNAUTHORIZED", "Tenant connection is not active.")

    drive_items = _load("drive_items.json")

    # Ensure parent folder drive item exists (upsert as direct_lookup if missing)
    parent = next((it for it in drive_items if it.get("tenant_id") == tenant_id and it.get("item_type") == "folder" and it.get("feishu_token") == folder_token), None)
    now = _now_iso()
    if parent is None:
        parent = {
            "id": _ulid_like("fs_drv_"),
            "tenant_id": tenant_id,
            "feishu_token": folder_token,
            "item_type": "folder",
            "title": None,
            "url": "https://drive.feishu.cn/drive/folder/" + folder_token,
            "parent_item_id": None,
            "owner_user_id": None,
            "created_by_user_id": None,
            "source": "direct_lookup",
            "status": "unknown",
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now
        }
        drive_items.append(parent)
        _save("drive_items.json", drive_items)
    else:
        parent["last_seen_at"] = now
        parent["updated_at"] = now
        if parent.get("status") in ("unknown", "inaccessible"):
            parent["status"] = "active"
        _save("drive_items.json", drive_items)

    op["target_drive_item_id"] = parent.get("id")
    _save("operations.json", ops)

    # Listing is served from cached children. Pagination via index over sorted by created_at then id.
    children = [it for it in drive_items if it.get("tenant_id") == tenant_id and it.get("parent_item_id") == parent.get("id")]

    def _status_ok(st):
        if include_deleted:
            return True
        return st not in ("deleted", "inaccessible")

    children = [c for c in children if _status_ok(c.get("status"))]

    def _sort_key(it):
        return (it.get("created_at") or "", it.get("id") or "")
    children.sort(key=_sort_key)

    start_idx = 0
    if page_token:
        try:
            start_idx = int(page_token)
            if start_idx < 0:
                start_idx = 0
        except Exception:
            _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="Invalid page_token.", duration_ms=int((time.time()-start)*1000))
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    page = children[start_idx:start_idx + page_size]
    next_idx = start_idx + len(page)
    has_more = next_idx < len(children)
    next_cursor = str(next_idx) if has_more else None

    # Business rule: items not returned over time may be marked unknown (not deleted) without explicit signal.
    # Here, since we're serving from cache, we treat returned items as "seen" and can optionally mark unseen as unknown.
    # We'll mark any cached child with status=active but last_seen_at older than 30 days as unknown (soft aging).
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=30)
    changed = False
    for it in children:
        ls = it.get("last_seen_at")
        if it.get("status") == "active" and ls:
            try:
                dt = datetime.datetime.fromisoformat(ls.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt < cutoff:
                it["status"] = "unknown"
                it["updated_at"] = _now_iso()
                changed = True
    # Mark returned items as seen/active (without forcing deleted->active)
    for it in page:
        it["last_seen_at"] = now
        if it.get("status") in ("unknown", "inaccessible"):
            it["status"] = "active"
        it["updated_at"] = now
        changed = True

    if changed:
        _save("drive_items.json", drive_items)

    response = {
        "tenant_id": tenant_id,
        "folder": {
            "drive_item_id": parent.get("id"),
            "folder_token": folder_token,
            "title": parent.get("title"),
            "url": parent.get("url"),
            "status": parent.get("status")
        },
        "items": [
            {
                "drive_item_id": it.get("id"),
                "item_type": it.get("item_type"),
                "token": it.get("feishu_token"),
                "title": it.get("title"),
                "url": it.get("url"),
                "status": it.get("status"),
                "owner_user_id": it.get("owner_user_id"),
                "created_by_user_id": it.get("created_by_user_id"),
                "last_seen_at": it.get("last_seen_at")
            } for it in page
        ],
        "pagination": {
            "page_size": page_size,
            "next_page_token": next_cursor,
            "has_more": has_more,
            "total_cached": len(children)
        }
    }
    _set_op_final(ops, op_id, "succeeded", response_json=response, duration_ms=int((time.time()-start)*1000))
    return response

def create_feishu_folder(tenant_id, parent_folder_token, title, idempotency_key=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        t = int(time.time() * 1000)
        ts = t
        out = []
        for _ in range(10):
            out.append(_CROCK[ts % 32])
            ts //= 32
        ts_part = "".join(reversed(out))
        rnd = "".join(_CROCK[(t * 1103515245 + 12345 + i * 2654435761) % 32] for i in range(16))
        return f"{prefix}{ts_part}{rnd}"

    def _validate_ulid(value, pattern, field):
        if not isinstance(value, str):
            return f"{field} must be a string"
        if not re.match(pattern, value):
            return f"{field} is invalid"
        return None

    def _record_op(ops, op):
        ops.append(op)
        _save("operations.json", ops)

    def _set_op_final(ops, op_id, status, response_json=None, error_code=None, error_message=None, duration_ms=None):
        now = _now_iso()
        for r in ops:
            if r.get("id") == op_id:
                r["status"] = status
                r["updated_at"] = now
                if duration_ms is not None:
                    r["duration_ms"] = duration_ms
                if response_json is not None:
                    r["response_json"] = response_json
                if error_code is not None:
                    r["error_code"] = error_code
                if error_message is not None:
                    r["error_message"] = error_message
                _save("operations.json", ops)
                return

    def _check_rate_limit(ops, tnt_id, is_write):
        if not is_write:
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops:
            if r.get("tenant_id") != tnt_id:
                continue
            ts = r.get("created_at")
            if not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= minute_ago:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded for tenant (writes per minute).", limit_per_minute=60)
        return None

    start = time.time()
    ops = _load("operations.json")

    v = _validate_ulid(tenant_id, r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", "tenant_id")

    op_id = _ulid_like("fs_op_")
    op = {
        "id": op_id,
        "tenant_id": tenant_id if isinstance(tenant_id, str) else "unknown",
        "tool_name": "create_feishu_folder",
        "request_json": {"tenant_id": tenant_id, "parent_folder_token": parent_folder_token, "title": title, "idempotency_key": idempotency_key},
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": idempotency_key,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso()
    }
    _record_op(ops, op)

    if v:
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message=v, duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", v)
    if not isinstance(parent_folder_token, str) or not parent_folder_token.strip():
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="parent_folder_token must be a non-empty string.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "parent_folder_token must be a non-empty string.")
    if not isinstance(title, str) or len(title.strip()) < 1:
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="title must be a non-empty string.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _set_op_final(ops, op_id, "failed", error_code="VALIDATION_ERROR", error_message="idempotency_key must be a string when provided.", duration_ms=int((time.time()-start)*1000))
        return _err("VALIDATION_ERROR", "idempotency_key must be a string when provided.")

    # Rate limit (write) must be rejected before "calling Feishu"
    rl = _check_rate_limit(ops, tenant_id, True)
    if rl:
        _set_op_final(ops, op_id, "failed", error_code=rl["error"]["code"], error_message=rl["error"]["message"], duration_ms=int((time.time()-start)*1000))
        return rl

    tenants = _load("tenants.json")
    tenant = next((t for t in tenants if t.get("id") == tenant_id), None)
    if not tenant:
        _set_op_final(ops, op_id, "failed", error_code="NOT_FOUND", error_message="Tenant not found.", duration_ms=int((time.time()-start)*1000))
        return _err("NOT_FOUND", "Tenant not found.")
    if tenant.get("status") != "active":
        _set_op_final(ops, op_id, "failed", error_code="UNAUTHORIZED", error_message="Tenant connection is not active.", duration_ms=int((time.time()-start)*1000))
        return _err("UNAUTHORIZED", "Tenant connection is not active.")

    drive_items = _load("drive_items.json")

    # Ensure parent exists (folder). Upsert unknown parent if missing.
    parent = next((it for it in drive_items if it.get("tenant_id") == tenant_id and it.get("item_type") == "folder" and it.get("feishu_token") == parent_folder_token), None)
    now = _now_iso()
    if parent is None:
        parent = {
            "id": _ulid_like("fs_drv_"),
            "tenant_id": tenant_id,
            "feishu_token": parent_folder_token,
            "item_type": "folder",
            "title": None,
            "url": "https://drive.feishu.cn/drive/folder/" + parent_folder_token,
            "parent_item_id": None,
            "owner_user_id": None,
            "created_by_user_id": None,
            "source": "direct_lookup",
            "status": "unknown",
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now
        }
        drive_items.append(parent)
        _save("drive_items.json", drive_items)

    # Idempotency: if idempotency_key succeeded earlier, return that response
    if idempotency_key:
        for r in ops:
            if r.get("tenant_id") == tenant_id and r.get("tool_name") == "create_feishu_folder" and r.get("idempotency_key") == idempotency_key and r.get("status") == "succeeded":
                resp = r.get("response_json")
                if resp and isinstance(resp, dict) and resp.get("folder") and resp["folder"].get("folder_token"):
                    # Verify drive item still exists
                    tok = resp["folder"]["folder_token"]
                    existing = next((it for it in drive_items if it.get("tenant_id") == tenant_id and it.get("item_type") == "folder" and it.get("feishu_token") == tok), None)
                    if existing:
                        op["target_drive_item_id"] = existing.get("id")
                        _save("operations.json", ops)
                        _set_op_final(ops, op_id, "succeeded", response_json=resp, duration_ms=int((time.time()-start)*1000))
                        return resp
                break

    # "Feishu returns token" - offline deterministic but unique enough
    token = "fld_" + _ulid_like("")[-20:]
    # Enforce uniqueness(tenant_id, feishu_token, item_type)
    if any(it for it in drive_items if it.get("tenant_id") == tenant_id and it.get("item_type") == "folder" and it.get("feishu_token") == token):
        token = "fld_" + _ulid_like("")[-20:]

    # Create drive item
    folder_id = _ulid_like("fs_drv_")
    url = "https://drive.feishu.cn/drive/folder/" + token
    row = {
        "id": folder_id,
        "tenant_id": tenant_id,
        "feishu_token": token,
        "item_type": "folder",
        "title": title.strip(),
        "url": url,
        "parent_item_id": parent.get("id"),
        "owner_user_id": tenant.get("default_user_id"),
        "created_by_user_id": tenant.get("default_user_id"),
        "source": "folder_list",
        "status": "active",
        "last_seen_at": now,
        "created_at": now,
        "updated_at": now
    }
    drive_items.append(row)
    _save("drive_items.json", drive_items)

    op["target_drive_item_id"] = folder_id
    _save("operations.json", ops)

    response = {
        "tenant_id": tenant_id,
        "folder": {
            "drive_item_id": folder_id,
            "parent_drive_item_id": parent.get("id"),
            "parent_folder_token": parent_folder_token,
            "folder_token": token,
            "title": row.get("title"),
            "url": row.get("url"),
            "status": row.get("status"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at")
        }
    }
    _set_op_final(ops, op_id, "succeeded", response_json=response, duration_ms=int((time.time()-start)*1000))
    return response

def create_feishu_tenant_connection(feishu_tenant_key, app_id, app_secret_ciphertext, default_user_id=None, scopes=None, validate=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _ulid_like(prefix):
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256((prefix + "|" + str(uuid.uuid4())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(crock[b % 32])
            if len(out) >= 26: break
        return prefix + "".join(out)

    def _check_rate_limit(ops_rows, is_write):
        if not is_write:
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops_rows:
            created = _parse_dt(r.get("created_at"))
            if created and created >= window_start:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Too many requests; retry later.", limit_per_minute=120)
        return None

    def _op_finish(ops_rows, op_row, status, response=None, code=None, msg=None):
        op_row["status"] = status
        op_row["updated_at"] = _now()
        op_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        if status == "succeeded":
            op_row["response_json"] = response if response is not None else {}
            op_row["error_code"] = None
            op_row["error_message"] = None
        else:
            op_row["response_json"] = response if response is not None else None
            op_row["error_code"] = code
            op_row["error_message"] = msg
        _save("operations.json", ops_rows)

    # Validate
    if not isinstance(feishu_tenant_key, str) or not feishu_tenant_key.strip():
        return _err("VALIDATION_ERROR", "feishu_tenant_key is required.", feishu_tenant_key=feishu_tenant_key)
    if not isinstance(app_id, str) or not app_id.strip():
        return _err("VALIDATION_ERROR", "app_id is required.", app_id=app_id)
    if not isinstance(app_secret_ciphertext, str) or not app_secret_ciphertext.strip():
        return _err("VALIDATION_ERROR", "app_secret_ciphertext is required.", app_secret_ciphertext=app_secret_ciphertext)
    if default_user_id is not None and (not isinstance(default_user_id, str) or not default_user_id.strip()):
        return _err("VALIDATION_ERROR", "default_user_id must be a non-empty string when provided.", default_user_id=default_user_id)
    if scopes is not None:
        if not isinstance(scopes, list) or any((not isinstance(s, str) or not s.strip()) for s in scopes):
            return _err("VALIDATION_ERROR", "scopes must be an array of strings when provided.", scopes=scopes)
    if validate is not None and not isinstance(validate, bool):
        return _err("VALIDATION_ERROR", "validate must be a boolean when provided.", validate=validate)
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.", idempotency_key=idempotency_key)

    tenants = _load("tenants.json")
    ops = _load("operations.json")

    # operations row (tenant_id unknown at start; set later if created)
    op_row = {
        "id": _ulid_like("fs_op_"),
        "tenant_id": None,
        "tool_name": "create_feishu_tenant_connection",
        "request_json": {
            "feishu_tenant_key": feishu_tenant_key,
            "app_id": app_id,
            "app_secret_ciphertext": app_secret_ciphertext,
            "default_user_id": default_user_id,
            "scopes": scopes,
            "validate": validate,
            "idempotency_key": idempotency_key,
        },
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": idempotency_key,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op_row)
    _save("operations.json", ops)

    # Rate limit
    rl = _check_rate_limit(ops, True)
    if rl:
        _op_finish(ops, op_row, "failed", response=None, code=rl["error"]["code"], msg=rl["error"]["message"])
        return rl

    # Idempotency: return existing tenant if key provided and already created
    if idempotency_key:
        for r in ops:
            if r is op_row:
                continue
            if r.get("tool_name") == "create_feishu_tenant_connection" and r.get("idempotency_key") == idempotency_key and r.get("status") == "succeeded":
                resp = r.get("response_json")
                if isinstance(resp, dict) and "tenant" in resp:
                    return resp
                return {"result": resp}

    # Enforce unique feishu_tenant_key
    existing = next((t for t in tenants if t.get("feishu_tenant_key") == feishu_tenant_key), None)
    if existing is not None:
        # idempotent behavior: if same app_id and ciphertext, return existing; else conflict
        if existing.get("app_id") == app_id and existing.get("app_secret_ciphertext") == app_secret_ciphertext:
            resp = {"tenant": existing, "operation_id": op_row.get("id"), "idempotency_key": idempotency_key, "created": False}
            op_row["tenant_id"] = existing.get("id")
            _op_finish(ops, op_row, "succeeded", response=resp)
            return resp
        _op_finish(ops, op_row, "failed", response=None, code="CONFLICT", msg="feishu_tenant_key already exists with different credentials.")
        return _err("CONFLICT", "feishu_tenant_key already exists with different credentials.", feishu_tenant_key=feishu_tenant_key)

    # validate=true cannot be performed offline; treat as accepted if ciphertext is non-empty
    if validate is True:
        # Since ciphertext can't be validated against Feishu offline, accept syntactically and do not error.
        pass

    now = _now()
    tenant_row = {
        "id": _ulid_like("fs_tnt_"),
        "feishu_tenant_key": feishu_tenant_key,
        "app_id": app_id,
        "app_secret_ciphertext": app_secret_ciphertext,
        "default_user_id": default_user_id,
        "access_token_ciphertext": None,
        "access_token_expires_at": None,
        "scopes": scopes if isinstance(scopes, list) else [],
        "status": "active",
        "last_error_code": None,
        "last_error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    tenants.append(tenant_row)
    _save("tenants.json", tenants)

    op_row["tenant_id"] = tenant_row["id"]
    resp = {"tenant": tenant_row, "operation_id": op_row.get("id"), "idempotency_key": idempotency_key, "created": True}
    _op_finish(ops, op_row, "succeeded", response=resp)
    return resp

def list_feishu_tenants(status=None, feishu_tenant_key=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "revoked", "error"):
            return _err("VALIDATION_ERROR", "status must be one of: active, revoked, error")
    if feishu_tenant_key is not None and (not isinstance(feishu_tenant_key, str) or not feishu_tenant_key.strip()):
        return _err("VALIDATION_ERROR", "feishu_tenant_key must be a non-empty string when provided")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")

    tenants = _load("tenants.json")
    operations = _load("operations.json")

    # Record operation (reads included)
    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        ts = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[ts % 32])
            ts //= 32
        ts_part = "".join(reversed(chars))
        rnd = os.urandom(10)
        v = int.from_bytes(rnd, "big")
        rchars = []
        for _ in range(16):
            rchars.append(alphabet[v % 32])
            v //= 32
        return f"{prefix}_{ts_part}{''.join(reversed(rchars))}"

    op_id = _ulid("fs_op")
    op = {
        "id": op_id,
        "tenant_id": None,
        "tool_name": "list_feishu_tenants",
        "request_json": {
            "status": status,
            "feishu_tenant_key": feishu_tenant_key,
            "page_size": page_size,
            "page_token": page_token
        },
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": None,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    }
    operations.append(op)
    _save("operations.json", operations)

    # Decode page_token as offset
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                return _err("VALIDATION_ERROR", "page_token is invalid")
        except Exception:
            # expected decoding errors
            for oop in operations:
                if oop.get("id") == op_id:
                    oop["status"] = "failed"
                    oop["error_code"] = "VALIDATION_ERROR"
                    oop["error_message"] = "page_token is invalid"
                    oop["duration_ms"] = int((time.time() - t0) * 1000)
                    oop["updated_at"] = now
                    break
            _save("operations.json", operations)
            return _err("VALIDATION_ERROR", "page_token is invalid")

    rows = tenants[:]
    if status is not None:
        rows = [t for t in rows if t.get("status") == status]
    if feishu_tenant_key is not None:
        rows = [t for t in rows if t.get("feishu_tenant_key") == feishu_tenant_key]

    # Order by created_at desc (string ISO Z sorts lexicographically)
    rows.sort(key=lambda r: (r.get("created_at") or ""), reverse=True)

    total = len(rows)
    page = rows[offset:offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "tenants": page,
        "total": total,
        "has_more": has_more,
        "next_page_token": next_token
    }

    for oop in operations:
        if oop.get("id") == op_id:
            oop["status"] = "succeeded"
            oop["response_json"] = {"count": len(page), "total": total, "has_more": has_more}
            oop["duration_ms"] = int((time.time() - t0) * 1000)
            oop["updated_at"] = now
            break
    _save("operations.json", operations)

    return resp

def update_feishu_tenant_status(tenant_id, status, last_error_code=None, last_error_message=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _err("VALIDATION_ERROR", "tenant_id is invalid")
    if not isinstance(status, str) or status not in ("active", "error", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, error, revoked")
    if last_error_code is not None and (not isinstance(last_error_code, str) or not last_error_code.strip()):
        return _err("VALIDATION_ERROR", "last_error_code must be a non-empty string when provided")
    if last_error_message is not None and (not isinstance(last_error_message, str) or not last_error_message.strip()):
        return _err("VALIDATION_ERROR", "last_error_message must be a non-empty string when provided")

    tenants = _load("tenants.json")
    operations = _load("operations.json")

    # log op first
    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        ts = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[ts % 32])
            ts //= 32
        ts_part = "".join(reversed(chars))
        rnd = os.urandom(10)
        v = int.from_bytes(rnd, "big")
        rchars = []
        for _ in range(16):
            rchars.append(alphabet[v % 32])
            v //= 32
        return f"{prefix}_{ts_part}{''.join(reversed(rchars))}"

    op_id = _ulid("fs_op")
    operations.append({
        "id": op_id,
        "tenant_id": tenant_id,
        "tool_name": "update_feishu_tenant_status",
        "request_json": {
            "tenant_id": tenant_id,
            "status": status,
            "last_error_code": last_error_code,
            "last_error_message": last_error_message
        },
        "target_drive_item_id": None,
        "target_document_id": None,
        "target_block_id": None,
        "status": "running",
        "idempotency_key": None,
        "feishu_request_id": None,
        "response_json": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now
    })
    _save("operations.json", operations)

    tenant = None
    for t in tenants:
        if t.get("id") == tenant_id:
            tenant = t
            break
    if tenant is None:
        for oop in operations:
            if oop.get("id") == op_id:
                oop["status"] = "failed"
                oop["error_code"] = "NOT_FOUND"
                oop["error_message"] = "tenant not found"
                oop["duration_ms"] = int((time.time() - t0) * 1000)
                oop["updated_at"] = now
                break
        _save("operations.json", operations)
        return _err("NOT_FOUND", "Tenant not found")

    current = tenant.get("status")
    transitions = {
        "active": {"error", "revoked"},
        "error": {"active", "revoked"},
        "revoked": set()
    }
    if current not in transitions:
        for oop in operations:
            if oop.get("id") == op_id:
                oop["status"] = "failed"
                oop["error_code"] = "INVALID_TRANSITION"
                oop["error_message"] = "unknown current tenant state"
                oop["duration_ms"] = int((time.time() - t0) * 1000)
                oop["updated_at"] = now
                break
        _save("operations.json", operations)
        return _err("INVALID_TRANSITION", "Unknown current tenant state", current_status=current)

    if status == current:
        # idempotent: succeed with no state change
        for oop in operations:
            if oop.get("id") == op_id:
                oop["status"] = "succeeded"
                oop["response_json"] = {"tenant": tenant, "idempotent": True}
                oop["duration_ms"] = int((time.time() - t0) * 1000)
                oop["updated_at"] = now
                break
        _save("operations.json", operations)
        return {"tenant": tenant}

    if status not in transitions[current]:
        for oop in operations:
            if oop.get("id") == op_id:
                oop["status"] = "failed"
                oop["error_code"] = "INVALID_TRANSITION"
                oop["error_message"] = "requested status transition not allowed"
                oop["duration_ms"] = int((time.time() - t0) * 1000)
                oop["updated_at"] = now
                break
        _save("operations.json", operations)
        return _err("INVALID_TRANSITION", "Transition not allowed", from_status=current, to_status=status)

    # Apply update
    tenant["status"] = status
    if status == "error":
        tenant["last_error_code"] = last_error_code
        tenant["last_error_message"] = last_error_message
    else:
        # clear errors when leaving error state
        tenant["last_error_code"] = None
        tenant["last_error_message"] = None
    tenant["updated_at"] = now
    _save("tenants.json", tenants)

    for oop in operations:
        if oop.get("id") == op_id:
            oop["status"] = "succeeded"
            oop["response_json"] = {"tenant": tenant}
            oop["duration_ms"] = int((time.time() - t0) * 1000)
            oop["updated_at"] = now
            break
    _save("operations.json", operations)

    return {"tenant": tenant}

def batch_update_feishu_blocks(tenant_id, document_id, operations, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0283000" if __import__("os").path.isdir("./environment_mix/0283000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0_all = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _ulid_like(prefix):
        crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = hashlib.sha256((prefix + "|" + str(uuid.uuid4())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(crock[b % 32])
            if len(out) >= 26:
                break
        return prefix + "".join(out)

    def _check_rate_limit(ops_rows, tnt_id):
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in ops_rows:
            if r.get("tenant_id") != tnt_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if created and created >= window_start:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Too many write operations for tenant in the last minute; retry later.", tenant_id=tnt_id, limit_per_minute=60)
        return None

    def _finish_op(ops_rows, op_id, started, status, response=None, code=None, msg=None):
        dur = max(0, int((time.time() - started) * 1000))
        for r in ops_rows:
            if r.get("id") == op_id:
                r["status"] = status
                r["updated_at"] = _now()
                r["duration_ms"] = dur
                if status == "succeeded":
                    r["response_json"] = response if response is not None else {}
                    r["error_code"] = None
                    r["error_message"] = None
                else:
                    r["response_json"] = response if response is not None else None
                    r["error_code"] = code
                    r["error_message"] = msg
                break

    # Validate inputs
    if not isinstance(tenant_id, str) or not re.match(r"^fs_tnt_[0-9A-HJKMNP-TV-Z]{10,}$", tenant_id):
        return _err("VALIDATION_ERROR", "Invalid tenant_id.", tenant_id=tenant_id)
    if not isinstance(document_id, str) or not document_id.strip():
        return _err("VALIDATION_ERROR", "document_id is required.", document_id=document_id)
    if not isinstance(operations, list) or len(operations) < 1:
        return _err("VALIDATION_ERROR", "operations must be a non-empty array.", operations=operations)
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.", idempotency_key=idempotency_key)

    tenants = _load("tenants.json")
    documents = _load("documents.json")
    blocks = _load("document_blocks.json")
    media_assets = _load("media_assets.json")
    ops_rows = _load("operations.json")

    # Resolve active tenant owning document if needed
    tnt = None
    for r in tenants:
        if r.get("id") == tenant_id:
            tnt = r
            break
    if not tnt or tnt.get("status") != "active":
        for d in documents:
            if d.get("id") == document_id:
                for r in tenants:
                    if r.get("id") == d.get("tenant_id") and r.get("status") == "active":
                        tnt = r
                        tenant_id = r.get("id")
                        break
                if tnt:
                    break
    if not tnt or tnt.get("status") != "active":
        # record an operation even for unauthorized
        op_id = _ulid_like("fs_op_")
        ops_rows.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "batch_update_feishu_blocks",
            "request_json": {"tenant_id": tenant_id, "document_id": document_id, "idempotency_key": idempotency_key, "operations": operations},
            "target_drive_item_id": None,
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "UNAUTHORIZED",
            "error_message": "No active tenant connection available for this request.",
            "duration_ms": max(0, int((time.time() - t0_all) * 1000)),
            "created_at": _now(),
            "updated_at": _now()
        })
        _save("operations.json", ops_rows)
        return _err("UNAUTHORIZED", "No active tenant connection available for this request.", tenant_id=tenant_id)

    # Find document by tenant
    doc_row = None
    for d in documents:
        if d.get("id") == document_id and d.get("tenant_id") == tenant_id:
            doc_row = d
            break
    if not doc_row:
        op_id = _ulid_like("fs_op_")
        ops_rows.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "batch_update_feishu_blocks",
            "request_json": {"tenant_id": tenant_id, "document_id": document_id, "idempotency_key": idempotency_key, "operations": operations},
            "target_drive_item_id": None,
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "failed",
            "idempotency_key": idempotency_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": "NOT_FOUND",
            "error_message": "Document not found for tenant.",
            "duration_ms": max(0, int((time.time() - t0_all) * 1000)),
            "created_at": _now(),
            "updated_at": _now()
        })
        _save("operations.json", ops_rows)
        return _err("NOT_FOUND", "Document not found for tenant.", tenant_id=tenant_id, document_id=document_id)

    # Idempotency at batch-level: if a succeeded batch exists, return it
    if idempotency_key:
        for r in ops_rows:
            if r.get("tenant_id") == tenant_id and r.get("tool_name") == "batch_update_feishu_blocks" and r.get("idempotency_key") == idempotency_key and r.get("status") == "succeeded":
                # record this call too (read-only replay)
                op_id = _ulid_like("fs_op_")
                ops_rows.append({
                    "id": op_id,
                    "tenant_id": tenant_id,
                    "tool_name": "batch_update_feishu_blocks",
                    "request_json": {"tenant_id": tenant_id, "document_id": document_id, "idempotency_key": idempotency_key, "operations": operations},
                    "target_drive_item_id": doc_row.get("drive_item_id"),
                    "target_document_id": document_id,
                    "target_block_id": None,
                    "status": "succeeded",
                    "idempotency_key": idempotency_key + ":retry",
                    "feishu_request_id": None,
                    "response_json": r.get("response_json") if isinstance(r.get("response_json"), dict) else {},
                    "error_code": None,
                    "error_message": None,
                    "duration_ms": max(0, int((time.time() - t0_all) * 1000)),
                    "created_at": _now(),
                    "updated_at": _now()
                })
                _save("operations.json", ops_rows)
                return r.get("response_json") if isinstance(r.get("response_json"), dict) else {"result": "succeeded", "idempotent_replay": True}

    # Validate operation payloads
    allowed_ops = {"create", "update_text", "delete"}
    allowed_block_types = {"text", "heading", "code", "list_item", "image", "divider", "quote", "callout", "table", "unknown"}
    for i, op in enumerate(operations):
        if not isinstance(op, dict):
            return _err("VALIDATION_ERROR", "Each operation must be an object.", index=i)
        if op.get("op") not in allowed_ops:
            return _err("VALIDATION_ERROR", "Invalid op.", index=i, op=op.get("op"))
        if op["op"] == "create":
            if not isinstance(op.get("parent_block_id"), str) or not op.get("parent_block_id").strip():
                return _err("VALIDATION_ERROR", "parent_block_id is required for create.", index=i)
            if op.get("index") is not None and (not isinstance(op.get("index"), int) or op.get("index") < 0):
                return _err("VALIDATION_ERROR", "index must be an integer >= 0 when provided.", index=i)
            if op.get("block_type") not in allowed_block_types:
                return _err("VALIDATION_ERROR", "block_type is required for create and must be valid.", index=i, block_type=op.get("block_type"))
            if op.get("block_type") in ("text", "heading", "code", "list_item") and (op.get("text") is None or not isinstance(op.get("text"), str)):
                return _err("VALIDATION_ERROR", "text is required for create of text-like blocks.", index=i)
            if op.get("block_type") == "heading" and op.get("heading_level") is not None:
                hl = op.get("heading_level")
                if not isinstance(hl, int) or hl < 1 or hl > 9:
                    return _err("VALIDATION_ERROR", "heading_level must be 1-9.", index=i, heading_level=hl)
        elif op["op"] == "update_text":
            if not isinstance(op.get("block_id"), str) or not op.get("block_id").strip():
                return _err("VALIDATION_ERROR", "block_id is required for update_text.", index=i)
            if not isinstance(op.get("text"), str):
                return _err("VALIDATION_ERROR", "text is required for update_text and must be a string.", index=i)
        elif op["op"] == "delete":
            if not isinstance(op.get("block_id"), str) or not op.get("block_id").strip():
                return _err("VALIDATION_ERROR", "block_id is required for delete.", index=i)
            if op.get("delete_count") is not None:
                dc = op.get("delete_count")
                if not isinstance(dc, int) or dc < 1 or dc > 500:
                    return _err("VALIDATION_ERROR", "delete_count must be between 1 and 500.", index=i, delete_count=dc)

    # Split into chunks of 50 "upstream calls"
    chunks = [operations[i:i + 50] for i in range(0, len(operations), 50)]
    prefix = idempotency_key or ("batch:" + document_id + ":" + hashlib.sha1(json.dumps(operations, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()[:12])

    per_chunk_results = []
    mutated_any = False

    for ci, chunk in enumerate(chunks):
        t0 = time.time()
        chunk_key = prefix + f":part{ci+1}of{len(chunks)}"
        # Create an operation row per upstream call
        op_id = _ulid_like("fs_op_")
        ops_rows.append({
            "id": op_id,
            "tenant_id": tenant_id,
            "tool_name": "batch_update_feishu_blocks",
            "request_json": {"tenant_id": tenant_id, "document_id": document_id, "idempotency_key": chunk_key, "operations": chunk},
            "target_drive_item_id": doc_row.get("drive_item_id"),
            "target_document_id": document_id,
            "target_block_id": None,
            "status": "running",
            "idempotency_key": chunk_key,
            "feishu_request_id": None,
            "response_json": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "created_at": _now(),
            "updated_at": _now()
        })

        rl = _check_rate_limit(ops_rows, tenant_id)
        if rl:
            _finish_op(ops_rows, op_id, t0, "failed", response=None, code="RATE_LIMIT", msg=rl["error"]["message"])
            per_chunk_results.append({"idempotency_key": chunk_key, "status": "failed", "error": rl["error"]})
            continue

        outcomes = []
        # apply chunk sequentially
        # map existing blocks by feishu_block_id for update_text/delete inputs (caller supplies feishu ids)
        doc_blocks = [b for b in blocks if b.get("tenant_id") == tenant_id and b.get("document_id") == document_id]
        by_feishu = {b.get("feishu_block_id"): b for b in doc_blocks if isinstance(b.get("feishu_block_id"), str)}
        by_internal = {b.get("id"): b for b in doc_blocks if isinstance(b.get("id"), str)}

        for oi, op in enumerate(chunk):
            if op["op"] == "create":
                now = _now()
                new_id = _ulid_like("fs_blk_")
                feishu_bid = "doxcnBlk" + hashlib.sha1((document_id + "|" + now + "|" + new_id).encode("utf-8")).hexdigest()[:10]
                new_block = {
                    "id": new_id,
                    "tenant_id": tenant_id,
                    "document_id": document_id,
                    "feishu_block_id": feishu_bid,
                    "parent_feishu_block_id": op.get("parent_block_id"),
                    "block_type": op.get("block_type"),
                    "index_in_parent": op.get("index") if isinstance(op.get("index"), int) else None,
                    "raw_block_payload": {"op": "create", "block_type": op.get("block_type")},
                    "text_plain": op.get("text") if op.get("block_type") in ("text", "heading", "code", "list_item") else None,
                    "heading_level": op.get("heading_level") if op.get("block_type") == "heading" else None,
                    "code_language": op.get("code_language") if op.get("block_type") == "code" else None,
                    "list_type": None,
                    "media_id": None,
                    "snapshot_version": int(doc_row.get("snapshot_version") or 0),
                    "status": "active",
                    "created_at": now,
                    "updated_at": now
                }
                blocks.append(new_block)
                mutated_any = True
                outcomes.append({"index": oi, "op": "create", "status": "succeeded", "block": new_block})
            elif op["op"] == "update_text":
                bid = op.get("block_id")
                blk = by_feishu.get(bid)
                if not blk:
                    outcomes.append({"index": oi, "op": "update_text", "status": "failed", "error": {"code": "NOT_FOUND", "message": "Block not found in cache.", "block_id": bid}})
                    continue
                if blk.get("block_type") not in ("text", "heading", "code", "list_item"):
                    outcomes.append({"index": oi, "op": "update_text", "status": "failed", "error": {"code": "VALIDATION_ERROR", "message": "Target block not eligible for update_text.", "block_type": blk.get("block_type")}})
                    continue
                blk["text_plain"] = op.get("text")
                blk["updated_at"] = _now()
                mutated_any = True
                outcomes.append({"index": oi, "op": "update_text", "status": "succeeded", "block": blk})
            elif op["op"] == "delete":
                start = op.get("block_id")
                blk = by_feishu.get(start)
                if not blk or blk.get("status") == "deleted":
                    outcomes.append({"index": oi, "op": "delete", "status": "failed", "error": {"code": "NOT_FOUND", "message": "Start block not found in cache.", "block_id": start}})
                    continue
                delete_count = op.get("delete_count") if isinstance(op.get("delete_count"), int) else 1
                parent = blk.get("parent_feishu_block_id")
                siblings = [b for b in doc_blocks if b.get("parent_feishu_block_id") == parent and b.get("status") != "deleted"]
                if not siblings or not all(isinstance(b.get("index_in_parent"), int) for b in siblings) or not isinstance(blk.get("index_in_parent"), int):
                    outcomes.append({"index": oi, "op": "delete", "status": "failed", "error": {"code": "VALIDATION_ERROR", "message": "Cannot validate consecutive delete without cached index_in_parent; refresh blocks first."}})
                    continue
                siblings_sorted = sorted(siblings, key=lambda x: x.get("index_in_parent"))
                pos = None
                for si, sb in enumerate(siblings_sorted):
                    if sb.get("feishu_block_id") == start:
                        pos = si
                        break
                if pos is None:
                    outcomes.append({"index": oi, "op": "delete", "status": "failed", "error": {"code": "NOT_FOUND", "message": "Start block not found among siblings.", "block_id": start}})
                    continue
                to_del = siblings_sorted[pos:pos + delete_count]
                for dblk in to_del:
                    dblk["status"] = "deleted"
                    dblk["updated_at"] = _now()
                mutated_any = True
                outcomes.append({"index": oi, "op": "delete", "status": "succeeded", "deleted_count": len(to_del), "deleted_block_ids": [b.get("feishu_block_id") for b in to_del]})

        # Persist mutations from this chunk
        if mutated_any:
            doc_row["updated_at"] = _now()
            _save("document_blocks.json", blocks)
            _save("documents.json", documents)
            _save("media_assets.json", media_assets)

        chunk_resp = {
            "idempotency_key": chunk_key,
            "status": "succeeded",
            "outcomes": outcomes
        }
        _finish_op(ops_rows, op_id, t0, "succeeded", response={"idempotency_key": chunk_key, "outcomes_count": len(outcomes)})
        per_chunk_results.append(chunk_resp)

    # Save operations log
    _save("operations.json", ops_rows)

    if not mutated_any:
        # no success without effect
        return _err("NOT_FOUND", "No mutations were applied (all operations failed or matched nothing).", tenant_id=tenant_id, document_id=document_id)

    resp = {
        "tenant_id": tenant_id,
        "document_id": document_id,
        "idempotency_key_prefix": prefix,
        "chunks": per_chunk_results,
        "snapshot_version": int(doc_row.get("snapshot_version") or 0),
        "duration_ms": max(0, int((time.time() - t0_all) * 1000))
    }

    # Record a top-level batch operation row too (as a convenience), succeeded only if at least one chunk succeeded
    top_op_id = _ulid_like("fs_op_")
    ops_rows = _load("operations.json")
    ops_rows.append({
        "id": top_op_id,
        "tenant_id": tenant_id,
        "tool_name": "batch_update_feishu_blocks",
        "request_json": {"tenant_id": tenant_id, "document_id": document_id, "idempotency_key": idempotency_key, "operations_count": len(operations)},
        "target_drive_item_id": doc_row.get("drive_item_id"),
        "target_document_id": document_id,
        "target_block_id": None,
        "status": "succeeded",
        "idempotency_key": idempotency_key,
        "feishu_request_id": None,
        "response_json": resp,
        "error_code": None,
        "error_message": None,
        "duration_ms": max(0, int((time.time() - t0_all) * 1000)),
        "created_at": _now(),
        "updated_at": _now()
    })
    _save("operations.json", ops_rows)
    return resp
